    # Water fills from bottom. A region with water level k means the k bottom-most cells 
    # (in terms of row) are water. But "below" means same column? Let me re-read.
    # "If a cell in a region is water, then all cells of that region below it are also water."
    # "below" typically means same column, greater row.
    # But "water level" - one consistent level. So water level h means all cells in region 
    # with row >= some threshold? Or all cells below a horizontal line?
    # Interpretation: there's a water level (a row number). All cells in the region at row >= level are water.
    # Actually a "water level" is a y-coordinate. Cells whose row index >= level_row are water.
    # So for each region, pick a threshold t. Cells (r,c) in region with r >= t are water.
    # t ranges such that num_water varies from 0 (t > max_row) to all cells (t <= min_row).

    # For each region, enumerate possible water configurations based on threshold
    region_options = {}
    for rid, cells in regions.items():
        rows_in_region = sorted(set(r for r, c in cells))
        options = []
        # Option: no water
        options.append(frozenset())
        # For each threshold = rows_in_region[i], water = cells with r >= threshold
        for t in rows_in_region:
            water = frozenset((r, c) for (r, c) in cells if r >= t)
            options.append(water)
        # dedupe
        seen = set()
        unique_opts = []
        for o in options:
            if o not in seen:
                seen.add(o)
                unique_opts.append(o)
        region_options[rid] = unique_opts

    region_ids = list(regions.keys())
    # Sort regions by number of options (ascending) for better pruning
    region_ids.sort(key=lambda x: len(region_options[x]))

    row_water = [0] * R
    col_water = [0] * C
    assignment = {}

    # Precompute for remaining regions, max possible water per row/col
    def compute_remaining_max(idx):
        max_row = [0] * R
        max_col = [0] * C
        for i in range(idx, len(region_ids)):
            rid = region_ids[i]
            best_r = [0] * R
            best_c = [0] * C
