                for rid, opt in assign_map.items():
                    for cell in opt:
                        all_water.add(cell)
                for (r, c) in all_water:
                    grid[r][c] = 'W'
                solution[0] = grid
            return

        rid = region_ids[idx]
        max_row, max_col = remaining_max_cache[idx + 1]

        for opt in region_options[rid]:
            # Check feasibility
            new_row = row_water[:]
            new_col = col_water[:]
            ok = True
            for (r, c) in opt:
                new_row[r] += 1
                new_col[c] += 1
                if new_row[r] > row_counts[r] or new_col[c] > col_counts[c]:
                    ok = False
                    break
            if not ok:
                continue
            # Check upper bound with remaining
            for r in range(R):
                if new_row[r] + max_row[r] < row_counts[r]:
                    ok = False
                    break
            if not ok:
                continue
            for c in range(C):
                if new_col[c] + max_col[c] < col_counts[c]:
                    ok = False
                    break
            if not ok:
                continue

            # Apply
            for r in range(R):
                row_water[r] = new_row[r]
            for c in range(C):
                col_water[c] = new_col[c]
            assign_map[rid] = opt

            backtrack(idx + 1)
            if solution[0] is not None:
                return

            # Revert
            for (r, c) in opt:
                row_water[r] -= 1
                col_water[c] -= 1
            del assign_map[rid]

    assign_map = {}
    backtrack(0)

    if solution[0] is None:
        return "No Solution"

    return '\n'.join(''.join('W' if cell == 'W' else '.' for cell in row) for row in solution[0])

