def solve(observation):
    region = observation['region']
    row_clues = observation['row_water_counts']
    col_clues = observation['col_water_counts']
    R = len(region)
    C = len(region[0])

    # For each region, get cells sorted by row descending (bottom first fills first)
    from collections import defaultdict
    region_cells = defaultdict(list)
    for r in range(R):
        for c in range(C):
            region_cells[region[r][c]].append((r, c))

    # For each region, determine possible water levels.
    # Water fills from bottom up. For each distinct row in region, 
    # "level k" means all cells with row >= (some threshold) are water.
    # Specifically: if water level is at row L (meaning water fills cells with row >= L in that region)
    # Possible levels: no water, or fill from row R_max down to some row R_min.
    # For each region, possible fill configurations: pick k = number of "bottom rows" filled.
    # But region shape can be irregular. The rule: if cell (r,c) is water, all cells in same region below it (same col? or any cell with greater row?) are water.
    # "all cells of that region below it" - means cells in the region with greater row index.
    # So water cells = all cells with row >= threshold_row for that region.
    # Let rows_in_region = sorted unique rows. Possible states: water_rows = set of rows from some row r* to max_row, OR empty.

    region_options = {}  # region_id -> list of (set of water cells, row_contribution dict, col_contribution dict)
    for rid, cells in region_cells.items():
        rows_set = sorted(set(r for r, c in cells))
        options = []
        # Option: no water
        options.append(frozenset())
        # Options: water from row threshold to bottom
        max_r = max(rows_set)
        for threshold in rows_set:
            water = frozenset((r, c) for r, c in cells if r >= threshold)
            options.append(water)
        # Deduplicate
        seen = set()
        unique_opts = []
        for o in options:
            if o not in seen:
                seen.add(o)
                unique_opts.append(o)
        region_options[rid] = unique_opts

    region_ids = list(region_options.keys())
    # Sort regions by number of options ascending, then by size descending for better pruning
    region_ids.sort(key=lambda x: (len(region_options[x]), -len(region_cells[x])))

    row_remaining = list(row_clues)
    col_remaining = list(col_clues)
    grid = [[None]*C for _ in range(R)]

    # Precompute for each region's options the row and col deltas
    opt_deltas = {}
    for rid, opts in region_options.items():
        deltas = []
        for opt in opts:
            rd = defaultdict(int)
            cd = defaultdict(int)
            for (r, c) in opt:
                rd[r] += 1
                cd[c] += 1
            deltas.append((opt, dict(rd), dict(cd)))
        opt_deltas[rid] = deltas

    # For pruning: compute max possible water per row/col from remaining regions
    def solve_rec(idx, row_rem, col_rem):
        if idx == len(region_ids):
            if all(x == 0 for x in row_rem) and all(x == 0 for x in col_rem):
                return True
            return False

        # Pruning: check if remaining regions can satisfy row/col constraints
        # Compute max possible additional water for each row/col from remaining regions
        max_row_add = [0]*R
        max_col_add = [0]*C
        min_row_add = [0]*R  # min is 0 (empty option always exists)
        min_col_add = [0]*C
        for i in range(idx, len(region_ids)):
            rid = region_ids[i]
            # max over options
            best_per_row = defaultdict(int)
            best_per_col = defaultdict(int)
            for opt, rd, cd in opt_deltas[rid]:
                for r, v in rd.items():
                    if v > best_per_row[r]:
                        best_per_row[r] = v
                for c, v in cd.items():
                    if v > best_per_col[c]:
                        best_per_col[c] = v
            for r, v in best_per_row.items():
                max_row_add[r] += v
            for c, v in best_per_col.items():
                max_col_add[c] += v

        for r in range(R):
            if row_rem[r] < 0 or row_rem[r] > max_row_add[r]:
                return False
        for c in range(C):
            if col_rem[c] < 0 or col_rem[c] > max_col_add[c]:
                return False

        rid = region_ids[idx]
        for opt, rd, cd in opt_deltas[rid]:
            # Check feasibility
            ok = True
            for r, v in rd.items():
                if row_rem[r] < v:
                    ok = False
                    break
            if not ok:
                continue
            for c, v in cd.items():
                if col_rem[c] < v:
                    ok = False
                    break
            if not ok:
                continue

            # Apply
            for r, v in rd.items():
                row_rem[r] -= v
            for c, v in cd.items():
                col_rem[c] -= v

            if solve_rec(idx + 1, row_rem, col_rem):
                for (r, c) in opt:
                    grid[r][c] = 'W'
                return True

            # Revert
            for r, v in rd.items():
                row_rem[r] += v
            for c, v in cd.items():
                col_rem[c] += v

        return False

    if solve_rec(0, row_remaining, col_remaining):
        return '\n'.join(''.join('W' if grid[r][c] == 'W' else '.' for c in range(C)) for r in range(R))
    return "No Solution"

