OBSERVATION = {
    'data': [[None, None, None, None], [None, None, None, None], [None, None, None, None], [None, None, None, None]],
    'horizontal': {'(0,1.5)': '<', '(0,2.5)': '>'},
    'vertical': {'(1.5,1)': 'v', '(2.5,0)': 'v', '(2.5,1)': 'v', '(2.5,3)': 'v'}
}

def solve(observation):
    data = observation['data']
    N = len(data)
    H = {}
    for k, v in observation['horizontal'].items():
        r, c = eval(k)
        H[(int(r), int(c - 0.5))] = v  # between (r,c) and (r,c+1)
    V = {}
    for k, v in observation['vertical'].items():
        r, c = eval(k)
        V[(int(r - 0.5), int(c))] = v  # between (r,c) and (r+1,c)

    # Initialize candidates
    cands = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                cands[r][c] = {data[r][c]}

    def propagate(cands):
        changed = True
        while changed:
            changed = False
            # Row/col uniqueness with singletons
            for r in range(N):
                for c in range(N):
                    if len(cands[r][c]) == 1:
                        v = next(iter(cands[r][c]))
                        for cc in range(N):
                            if cc != c and v in cands[r][cc]:
                                cands[r][cc].discard(v)
                                changed = True
                                if not cands[r][cc]: return False
                        for rr in range(N):
                            if rr != r and v in cands[rr][c]:
                                cands[rr][c].discard(v)
                                changed = True
                                if not cands[rr][c]: return False
            # Inequality constraints
            for (r, c), sym in H.items():
                a, b = cands[r][c], cands[r][c+1]
                if sym == '<':
                    maxb = max(b)
                    new_a = {x for x in a if x < maxb}
                    mina = min(new_a) if new_a else None
                    new_b = {x for x in b if mina is not None and x > mina}
                else:
                    minb = min(b)
                    new_a = {x for x in a if x > minb}
                    maxa = max(new_a) if new_a else None
                    new_b = {x for x in b if maxa is not None and x < maxa}
                if new_a != a:
                    cands[r][c] = new_a; changed = True
                    if not new_a: return False
                if new_b != b:
                    cands[r][c+1] = new_b; changed = True
                    if not new_b: return False
            for (r, c), sym in V.items():
                a, b = cands[r][c], cands[r+1][c]
                if sym == 'v':  # top > bottom? 'v' means top>bottom (arrow points down to smaller)
                    # Actually 'v' arrow points down means upper > lower
                    minb = min(b)
                    new_a = {x for x in a if x > minb}
                    maxa = max(new_a) if new_a else None
                    new_b = {x for x in b if maxa is not None and x < maxa}
                else:  # '^'
                    maxb = max(b)
                    new_a = {x for x in a if x < maxb}
                    mina = min(new_a) if new_a else None
                    new_b = {x for x in b if mina is not None and x > mina}
                if new_a != a:
                    cands[r][c] = new_a; changed = True
                    if not new_a: return False
                if new_b != b:
                    cands[r+1][c] = new_b; changed = True
                    if not new_b: return False
        return True

    def solve_rec(cands):
        if not propagate(cands):
            return None
        # Find cell with fewest candidates > 1
        best = None
        for r in range(N):
            for c in range(N):
                l = len(cands[r][c])
                if l > 1 and (best is None or l < best[0]):
                    best = (l, r, c)
        if best is None:
            return [[next(iter(cands[r][c])) for c in range(N)] for r in range(N)]
        _, r, c = best
        for v in list(cands[r][c]):
            new_cands = [[set(s) for s in row] for row in cands]
            new_cands[r][c] = {v}
            res = solve_rec(new_cands)
            if res is not None:
                return res
        return None

    result = solve_rec(cands)
    if result is None:
        return "No Solution"
    return str(result)

