        r_half = float(k[0])
        c = int(float(k[1]))
        row_top = int(r_half - 0.5)
        row_bot = row_top + 1
        if sym == '^':
            less_than.append(((row_top, c), (row_bot, c)))
        else:
            less_than.append(((row_bot, c), (row_top, c)))

    # Build constraint map per cell
    # greater_neighbors[cell] = list of cells that must be greater than cell
    # less_neighbors[cell] = list of cells that must be less than cell
    greater_neighbors = {(r,c): [] for r in range(N) for c in range(N)}
    less_neighbors = {(r,c): [] for r in range(N) for c in range(N)}
    for small, large in less_than:
        greater_neighbors[small].append(large)
        less_neighbors[large].append(small)

    # Candidates for each cell
    candidates = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
