                    if len(positions) == 1 and len(cands[r][positions[0]]) > 1:
                        cands[r][positions[0]] = {v}
                        changed = True
            for c in range(N):
                for v in range(1, N+1):
                    positions = [r for r in range(N) if v in cands[r][c]]
                    if len(positions) == 0:
                        return False
                    if len(positions) == 1 and len(cands[positions[0]][c]) > 1:
                        cands[positions[0]][c] = {v}
                        changed = True
        return True

    if not propagate(candidates):
        return "No Solution"

