def solve(observation):
    data = [row[:] for row in observation['data']]
    N = len(data)

    # Parse inequalities into constraints between adjacent cells
    # constraints: list of (r1,c1,r2,c2) meaning value at (r1,c1) < value at (r2,c2)
    less_than = []  # (a, b) means cell a < cell b

    for key, sym in observation.get('horizontal', {}).items():
        # key like '(row,col+0.5)'
        s = key.strip('()')
        parts = s.split(',')
        r = int(float(parts[0]))
        c_val = float(parts[1])
        # between (r, floor(c_val)) and (r, floor(c_val)+1)
        c_left = int(c_val - 0.5)
        c_right = c_left + 1
        if not (0 <= r < N and 0 <= c_left < N and 0 <= c_right < N):
            continue
        if sym == '<':
            less_than.append(((r, c_left), (r, c_right)))
        elif sym == '>':
            less_than.append(((r, c_right), (r, c_left)))

    for key, sym in observation.get('vertical', {}).items():
        s = key.strip('()')
        parts = s.split(',')
        r_val = float(parts[0])
        c = parts[1]
        try:
            c = int(float(c))
        except:
            continue
        r_top = int(r_val - 0.5)
        r_bot = r_top + 1
        if not (0 <= c < N and 0 <= r_top < N and 0 <= r_bot < N):
            continue
        # '^' means top < bottom? Actually '^' points up, meaning the cell below is smaller than above? 
        # Convention: '^' at (r+0.5, c) between (r,c) above and (r+1,c) below. '^' points up -> larger side is up? 
        # Typically in Futoshiki, ^ means the cell above is smaller (arrow points to smaller). Let me use: arrow points to smaller value.
        # '^' points up -> top cell is smaller: (r_top) < (r_bot)
        # 'v' points down -> bottom cell is smaller: (r_bot) < (r_top)
        if sym == '^':
            less_than.append(((r_top, c), (r_bot, c)))
        elif sym == 'v':
            less_than.append(((r_bot, c), (r_top, c)))

    # For horizontal, similar convention: '<' means left < right (arrow points to smaller). 
    # Actually '<' symbol: opening faces right, so left is smaller. left < right. That's what I have.

    # Build adjacency for quick lookup
    # lt_map: dict cell -> list of cells that must be greater
    # gt_map: dict cell -> list of cells that must be smaller
    lt_map = {}  # cell -> set of cells that must be > this cell
    gt_map = {}  # cell -> set of cells that must be < this cell
    for a, b in less_than:
        lt_map.setdefault(a, set()).add(b)
        gt_map.setdefault(b, set()).add(a)

    # Initialize candidates
    cands = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                cands[r][c] = {data[r][c]}

    def propagate():
        changed = True
        while changed:
            changed = False
            # Row/col uniqueness: if a cell is singleton, remove from peers
            for r in range(N):
                for c in range(N):
                    if len(cands[r][c]) == 1:
                        v = next(iter(cands[r][c]))
                        for cc in range(N):
                            if cc != c and v in cands[r][cc]:
                                cands[r][cc].discard(v)
                                if not cands[r][cc]:
                                    return False
                                changed = True
                        for rr in range(N):
                            if rr != r and v in cands[rr][c]:
                                cands[rr][c].discard(v)
                                if not cands[rr][c]:
                                    return False
                                changed = True

            # Inequality propagation: for a<b, max(a) < max(b) meaningful: a's max < max(b), b's min > min(a)
            for a, b in less_than:
                ra, ca = a
                rb, cb = b
                # a < b: a's values must be < max(b), b's values must be > min(a)
                max_b = max(cands[rb][cb]) if cands[rb][cb] else 0
                min_a = min(cands[ra][ca]) if cands[ra][ca] else N+1
                new_a = {v for v in cands[ra][ca] if v < max_b}
                new_b = {v for v in cands[rb][cb] if v > min_a}
                if new_a != cands[ra][ca]:
                    cands[ra][ca] = new_a
                    if not new_a:
                        return False
                    changed = True
                if new_b != cands[rb][cb]:
                    cands[rb][cb] = new_b
                    if not new_b:
                        return False
                    changed = True

            # Hidden singles: in each row/col, if value only fits in one cell
            for r in range(N):
                for v in range(1, N+1):
                    spots = [c for c in range(N) if v in cands[r][c]]
                    if len(spots) == 0:
                        return False
                    if len(spots) == 1 and len(cands[r][spots[0]]) > 1:
                        cands[r][spots[0]] = {v}
                        changed = True
            for c in range(N):
                for v in range(1, N+1):
                    spots = [r for r in range(N) if v in cands[r][c]]
                    if len(spots) == 0:
                        return False
                    if len(spots) == 1 and len(cands[spots[0]][c]) > 1:
                        cands[spots[0]][c] = {v}
                        changed = True
        return True

    if not propagate():
        return "No Solution"

    def is_complete():
        for r in range(N):
            for c in range(N):
                if len(cands[r][c]) != 1:
                    return False
        return True

    def backtrack():
        if is_complete():
            return True
        # Find cell with fewest candidates
        best = None
        best_len = N+1
        for r in range(N):
            for c in range(N):
                l = len(cands[r][c])
                if 1 < l < best_len:
                    best_len = l
                    best = (r, c)
        if best is None:
            return True
        r, c = best
        saved = [[cands[i][j].copy() for j in range(N)] for i in range(N)]
        for v in sorted(cands[r][c]):
            cands[r][c] = {v}
            if propagate() and backtrack():
                return True
            for i in range(N):
                for j in range(N):
                    cands[i][j] = saved[i][j].copy()
        return False

    if not backtrack():
        return "No Solution"

    result = [[next(iter(cands[r][c])) for c in range(N)] for r in range(N)]
    return result


