                                if not domains[rr][c]: return False
                                changed = True

            # Inequality propagation
            # Horizontal: h_cons[(r,c)] between (r,c) and (r,c+1)
            for (r,c), sym in h_cons.items():
                if c+1 >= N: continue
                d1 = domains[r][c]
                d2 = domains[r][c+1]
