                    new2 = {x for x in d2 if x < max1}
                    if new1 != d1:
                        domains[r][c] = new1
                        if not new1: return False
                        changed = True
                    if new2 != d2:
                        domains[r][c+1] = new2
                        if not new2: return False
                        changed = True

            for (r,c), sym in v_cons.items():
                if r+1 >= N: continue
                d1 = domains[r][c]
                d2 = domains[r+1][c]
                if sym == '^':
                    # (r,c) < (r+1,c)? '^' points up meaning upper cell smaller
                    # '^' at (r+0.5, c) between (r,c) and (r+1,c): arrow points up to smaller
                    # Actually convention: ^ means top < bottom (arrow points to smaller? or larger?)
