                    max2 = max(d2); min1 = min(d1)
                    new1 = {x for x in d1 if x < max2}
                    new2 = {x for x in d2 if x > min1}
                    if new1 != d1:
                        domains[r][c] = new1
                        if not new1: return False
                        changed = True
                    if new2 != d2:
                        domains[r+1][c] = new2
                        if not new2: return False
                        changed = True
                else:  # v: top > bottom
                    min2 = min(d2); max1 = max(d1)
                    new1 = {x for x in d1 if x > min2}
                    new2 = {x for x in d2 if x < max1}
                    if new1 != d1:
                        domains[r][c] = new1
                        if not new1: return False
                        changed = True
                    if new2 != d2:
                        domains[r+1][c] = new2
                        if not new2: return False
                        changed = True

            # Hidden singles
            for r in range(N):
                for v in range(1, N+1):
                    cells = [c for c in range(N) if v in domains[r][c]]
                    if len(cells) == 0: return False
                    if len(cells) == 1 and len(domains[r][cells[0]]) > 1:
                        domains[r][cells[0]] = {v}
                        changed = True
            for c in range(N):
                for v in range(1, N+1):
                    cells = [r for r in range(N) if v in domains[r][c]]
                    if len(cells) == 0: return False
                    if len(cells) == 1 and len(domains[cells[0]][c]) > 1:
                        domains[cells[0]][c] = {v}
                        changed = True
        return True

    if not propagate(domains):
        return "No Solution"

    def backtrack(domains):
        # find cell with smallest domain >1
        best = None
        for r in range(N):
            for c in range(N):
                l = len(domains[r][c])
                if l > 1:
                    if best is None or l < best[0]:
                        best = (l, r, c)
        if best is None:
            return domains
        _, r, c = best
        for v in sorted(domains[r][c]):
            new_d = [[set(s) for s in row] for row in domains]
            new_d[r][c] = {v}
            if propagate(new_d):
                res = backtrack(new_d)
                if res: return res
        return None

    result = backtrack(domains)
    if not result:
        return "No Solution"

    grid = [[next(iter(result[r][c])) for c in range(N)] for r in range(N)]
    return '\n'.join(' '.join(str(x) for x in row) for row in grid)

