    N = len(islands)

    # neighbors for each island: dict direction -> neighbor index
    # directions: 0=N,1=E,2=S,3=W
    neighbors = [dict() for _ in range(N)]
    for i, (r, c, v) in enumerate(islands):
        # North
        for rr in range(r-1, -1, -1):
            if (rr, c) in idx_of:
                neighbors[i][0] = idx_of[(rr, c)]
                break
        # South
        for rr in range(r+1, R):
