                edges.append((a, b))
    E = len(edges)

    # For each edge, determine cells it passes through (exclusive of endpoints)
    edge_cells = []
    for (a, b) in edges:
        r1, c1, _ = islands[a]
        r2, c2, _ = islands[b]
        cells = []
        if r1 == r2:
