            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return len(seen) == N

    def backtrack(assign):
        ok, assign = propagate(assign)
        if not ok:
            return None
        # pick unassigned edge with fewest choices / most constrained island
        unassigned = [e for e in range(E) if assign[e] is None]
        if not unassigned:
