            new_assign = assign[:]
            new_assign[best_eid] = val
            if val > 0:
                conflict = False
                for ce in crossings[best_eid]:
                    if new_assign[ce] is None:
                        new_assign[ce] = 0
                    elif new_assign[ce] > 0:
                        conflict = True
