        for val in [2, 1, 0]:
            lo, hi = bounds[best_eid]
            if val < lo or val > hi:
                continue
            new_assign = assign[:]
            new_assign[best_eid] = val
            if val > 0:
                conflict = False
                for ce in crossings[best_eid]:
                    if new_assign[ce] is None:
                        new_assign[ce] = 0
                    elif new_assign[ce] > 0:
                        conflict = True
                        break
                if conflict:
                    continue
            result = backtrack(new_assign)
            if result is not None:
                return result
        return None

    result = backtrack(assignment)
    if result is None:
        return "No Solution"

    answer = {}
    for eid, v in enumerate(result):
