def solve(observation):
    region = observation['region']
    data = observation['data']
    N = len(region)

    # Build region info
    region_cells = {}
    for r in range(N):
        for c in range(N):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append((r, c))

    # Region clues
    region_clue = {}
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                region_clue[region[r][c]] = data[r][c]

    # grid: 'B', 'W', or None
    # Precompute for each cell its region
    cell_region = [[region[r][c] for c in range(N)] for r in range(N)]

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < N:
                yield nr, nc

    def check_white_connected(grid):
        # All white cells must be connected
        start = None
        white_count = 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] != 'B':
                    white_count += 1
                    if start is None:
                        start = (r, c)
        if start is None:
            return True
        visited = set([start])
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] != 'B':
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return len(visited) == white_count

    def check_white_connected_possible(grid):
        # Treat unknowns as white - if even then not connected, fail
        start = None
        total = 0
        for r in range(N):
            for c in range(N):
                if grid[r][c] != 'B':
                    total += 1
                    if start is None:
                        start = (r, c)
        if start is None:
            return True
        visited = set([start])
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] != 'B':
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return len(visited) == total

    def check_straight_line(grid, final=False):
        # Check each row and column - maximal white runs
        # A white run is maximal sequence of non-B cells
        # It cannot pass through more than 2 regions
        for r in range(N):
            c = 0
            while c < N:
                if grid[r][c] == 'B':
                    c += 1
                    continue
                # start white run
                start = c
                regions_in_run = set()
                while c < N and grid[r][c] != 'B':
                    if grid[r][c] == 'W' or (final and grid[r][c] is None):
                        regions_in_run.add(region[r][c])
                    elif grid[r][c] is None:
                        # treat as potentially white
                        regions_in_run.add(region[r][c])
                    c += 1
                if len(regions_in_run) > 2:
                    # if any of the cells are unknowns, could still be ok if black
                    # but for pruning: if the confirmed whites already span >2 regions, fail
                    confirmed = set()
                    for cc in range(start, c):
                        if grid[r][cc] == 'W':
                            confirmed.add(region[r][cc])
                    if len(confirmed) > 2:
                        return False
                    if final and len(regions_in_run) > 2:
                        return False
        for c in range(N):
            r = 0
            while r < N:
                if grid[r][c] == 'B':
                    r += 1
                    continue
                start = r
                regions_in_run = set()
                while r < N and grid[r][c] != 'B':
                    regions_in_run.add(region[r][c])
                    r += 1
                if len(regions_in_run) > 2:
                    confirmed = set()
                    for rr in range(start, r):
                        if grid[rr][c] == 'W':
                            confirmed.add(region[rr][c])
                    if len(confirmed) > 2:
                        return False
                    if final and len(regions_in_run) > 2:
                        return False
        return True

    def check_region_counts(grid, final=False):
        for rid, cells in region_cells.items():
            b_count = sum(1 for (r,c) in cells if grid[r][c] == 'B')
            unk = sum(1 for (r,c) in cells if grid[r][c] is None)
            if rid in region_clue:
                target = region_clue[rid]
                if b_count > target:
                    return False
                if b_count + unk < target:
                    return False
                if final and b_count != target:
                    return False
        return True

    def check_adjacency(grid):
        for r in range(N):
            for c in range(N):
                if grid[r][c] == 'B':
                    for nr, nc in neighbors(r, c):
                        if grid[nr][nc] == 'B':
                            return False
        return True

    def propagate(grid):
        # Repeated deductions until stable
        changed = True
        while changed:
            changed = False
            # Rule: if cell is B, all neighbors must be W
            for r in range(N):
                for c in range(N):
                    if grid[r][c] == 'B':
                        for nr, nc in neighbors(r, c):
                            if grid[nr][nc] is None:
                                grid[nr][nc] = 'W'
                                changed = True
                            elif grid[nr][nc] == 'B':
                                return False

            # Rule: region count constraints
            for rid, cells in region_cells.items():
                if rid not in region_clue:
                    continue
                target = region_clue[rid]
                b_count = sum(1 for (r,c) in cells if grid[r][c] == 'B')
                unknowns = [(r,c) for (r,c) in cells if grid[r][c] is None]
                if b_count > target:
                    return False
                if b_count == target:
                    for (r,c) in unknowns:
                        grid[r][c] = 'W'
                        changed = True
                elif b_count + len(unknowns) == target:
                    for (r,c) in unknowns:
                        grid[r][c] = 'B'
                        changed = True
                elif b_count + len(unknowns) < target:
                    return False

            if not check_adjacency(grid):
                return False
            if not check_straight_line(grid):
                return False
        return True

    # Initial grid
    grid = [[None]*N for _ in range(N)]
    # Regions with clue 0 -> all cells white
    for rid, target in region_clue.items():
        if target == 0:
            for (r,c) in region_cells[rid]:
                grid[r][c] = 'W'

    if propagate(grid) is False:
        return "No Solution"

    # Choose unknown cell with fewest options (in constrained region)
    # Prefer cells in clued regions first, smallest remaining
    def pick_cell(grid):
        best = None
        best_score = float('inf')
        for rid, cells in region_cells.items():
            if rid not in region_clue:
                continue
            target = region_clue[rid]
            b_count = sum(1 for (r,c) in cells if grid[r][c] == 'B')
            unk = [(r,c) for (r,c) in cells if grid[r][c] is None]
            if not unk:
                continue
            remaining = target - b_count
            # score: smaller region with constraints = higher priority
            score = len(unk)
            if score < best_score:
                best_score = score
                best = unk[0]
        if best:
            return best
        # Any unknown
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    return (r, c)
        return None

    def copy_grid(g):
        return [row[:] for row in g]

    solution = [None]

    def backtrack(grid):
        if solution[0] is not None:
            return
        cell = pick_cell(grid)
        if cell is None:
            # All filled
            if not check_region_counts(grid, final=True):
                return
            if not check_adjacency(grid):
                return
            if not check_straight_line(grid, final=True):
                return
            if not check_white_connected(grid):
                return
            solution[0] = copy_grid(grid)
            return
        r, c = cell
        for val in ['B', 'W']:
            new_grid = copy_grid(grid)
            new_grid[r][c] = val
            if propagate(new_grid) is False:
                continue
            if not check_white_connected_possible(new_grid):
                continue
            backtrack(new_grid)
            if solution[0] is not None:
                return

    backtrack(grid)

    if solution[0] is None:
        return "No Solution"

    result = [[None]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if solution[0][r][c] == 'B':
                result[r][c] = 'B'
            else:
                result[r][c] = None
    return result

