            by_val.setdefault(v, []).append(r)
        for v, rows in by_val.items():
            if len(rows) > 1:
                for i in range(len(rows)):
                    for j in range(len(rows)):
                        if i != j:
                            duplicates[(rows[i],c)].append((rows[j],c))

    def neighbors(r, c):
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < M:
                yield nr, nc

    def check_connectivity(state):
        # All non-black cells must be connected. Also unknown counts as potentially white.
        # For safety: check that all white+unknown are connected.
        start = None
        for r in range(N):
            for c in range(M):
                if state[r][c] != 2:
                    start = (r,c)
                    break
            if start: break
        if not start:
            return False
        seen = set()
        stack = [start]
        seen.add(start)
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr,nc) not in seen and state[nr][nc] != 2:
                    seen.add((nr,nc))
                    stack.append((nr,nc))
        for r in range(N):
            for c in range(M):
