        if state[r][c] == 2: return False
        if state[r][c] == 1: return True
        state[r][c] = 1
        # all duplicates must be black
        for (r2,c2) in duplicates[(r,c)]:
            if not set_black(state, r2, c2):
                return False
        return True

    def set_black(state, r, c):
        if state[r][c] == 1: return False
        if state[r][c] == 2: return True
        state[r][c] = 2
        # all neighbors must be white
        for nr, nc in neighbors(r, c):
            if not set_white(state, nr, nc):
                return False
        return True

    def propagate(state):
