# Col c target = sum of (row+1) for black cells in that column

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    # For each row, enumerate subsets of columns whose weights sum to row_sum[r]
    # Column weights are 1..C
    def subsets_sum(weights, target):
        results = []
        n = len(weights)
        def rec(i, remaining, chosen):
            if remaining == 0:
                results.append(tuple(chosen))
                return
            if i >= n:
                return
            # prune: max possible remaining
            max_rem = sum(weights[i:])
            if remaining > max_rem:
                return
            if weights[i] <= remaining:
                chosen.append(i)
                rec(i+1, remaining - weights[i], chosen)
                chosen.pop()
            rec(i+1, remaining, chosen)
        rec(0, target, [])
        return results

    col_weights = list(range(1, C+1))
    row_weights = list(range(1, R+1))

    # Candidates per row: list of frozensets (or tuples) of column indices
    row_candidates = []
    for r in range(R):
        cands = subsets_sum(col_weights, row_sum[r])
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Order rows by number of candidates (fewest first)
    row_order = sorted(range(R), key=lambda r: len(row_candidates[r]))

    # State: for each column, current sum of row weights from selected rows, and remaining rows
    col_current = [0]*C
    # remaining potential for column c = sum of row_weights[r] for r not yet decided
    # We'll process rows in row_order; track which rows remain

    chosen_sets = [None]*R

    # Precompute for pruning: remaining row weight sums available for each column after index k in row_order
    remaining_weight_after = [0]*(len(row_order)+1)
    for i in range(len(row_order)-1, -1, -1):
        remaining_weight_after[i] = remaining_weight_after[i+1] + row_weights[row_order[i]]

    def backtrack(idx):
        if idx == len(row_order):
            for c in range(C):
                if col_current[c] != col_sum[c]:
                    return False
            return True
        r = row_order[idx]
        rw = row_weights[r]
        rem_after = remaining_weight_after[idx+1]
        for cand in row_candidates[r]:
            cand_set = set(cand)
            # Check column constraints
            ok = True
            for c in range(C):
                if c in cand_set:
                    new_val = col_current[c] + rw
                else:
                    new_val = col_current[c]
                if new_val > col_sum[c]:
                    ok = False
                    break
                # remaining weight for this column after idx
                if new_val + rem_after < col_sum[c]:
                    ok = False
                    break
            if not ok:
                continue
            # Apply
            for c in cand:
                col_current[c] += rw
            chosen_sets[r] = cand_set
            if backtrack(idx+1):
                return True
            for c in cand:
                col_current[c] -= rw
            chosen_sets[r] = None
        return False

    if not backtrack(0):
        return "No Solution"

    grid = [[None]*C for _ in range(R)]
    for r in range(R):
        for c in chosen_sets[r]:
            grid[r][c] = 'B'

    return '\n'.join(''.join('B' if grid[r][c]=='B' else '.' for c in range(C)) for r in range(R))

