            ok = True
            for c in range(C):
                bit = (mask >> c) & 1
                new_val = col_current[c] + (w if bit else 0)
                if new_val > col_sum[c]:
                    ok = False
                    break
                # max achievable = new_val + remaining_after
                if new_val + remaining_after < col_sum[c]:
                    ok = False
                    break
            if not ok:
                continue
            # apply
            for c in range(C):
                if (mask >> c) & 1:
                    col_current[c] += w
            chosen[r] = mask
            if backtrack(idx+1):
                return True
            for c in range(C):
                if (mask >> c) & 1:
                    col_current[c] -= w
        return False

    if not backtrack(0):
        return "No Solution"

    grid = [[None]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if (chosen[r] >> c) & 1:
                grid[r][c] = 'B'
    return str(grid)

