# Kuromasu / Kurodoko solver
# Rules:
# - Shade cells black; clue numbers count visible white cells orthogonally (including self) until blocked
# - Clues stay white
# - Black cells cannot be orthogonally adjacent
# - All white cells must be orthogonally connected

import sys
sys.setrecursionlimit(10000)

def solve(observation):
    grid = observation['data']
    N = len(grid)
    M = len(grid[0])

    # State: 0 = unknown, 1 = white, 2 = black
    # Clues are fixed white
    state = [[0]*M for _ in range(N)]
    clues = []
    for r in range(N):
        for c in range(M):
            if grid[r][c] is not None:
                state[r][c] = 1
                clues.append((r, c, grid[r][c]))

    def neighbors(r, c):
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < N and 0 <= nc < M:
                yield nr, nc

    def count_visible(st, r, c):
        # min visible (only currently known white), max visible (assuming unknown are white)
        # returns (min_vis, max_vis)
        min_v = 1
        max_v = 1
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            nr, nc = r+dr, c+dc
            # min: stop at unknown or black
            mn = 0
            tr, tc = nr, nc
            while 0 <= tr < N and 0 <= tc < M and st[tr][tc] == 1:
                mn += 1
                tr += dr; tc += dc
            min_v += mn
            # max: stop only at known black or border
            mx = 0
            tr, tc = nr, nc
            while 0 <= tr < N and 0 <= tc < M and st[tr][tc] != 2:
                mx += 1
                tr += dr; tc += dc
            max_v += mx
        return min_v, max_v

    def check_clues(st):
        for r, c, n in clues:
            mn, mx = count_visible(st, r, c)
            if n < mn or n > mx:
                return False
        return True

    def check_adjacency(st):
        # no two black adjacent
        for r in range(N):
            for c in range(M):
                if st[r][c] == 2:
                    for nr, nc in neighbors(r, c):
                        if st[nr][nc] == 2:
                            return False
        return True

    def check_connectivity(st):
        # All white (state==1) must be connected; treat unknowns as potentially white
        # For strict check (when fully determined), check connectivity of whites
        # For partial check: no confirmed white should be isolated from others by only blacks
        # Find a white cell
        start = None
        for r in range(N):
            for c in range(M):
                if st[r][c] == 1:
                    start = (r, c); break
            if start: break
        if not start:
            return True
        # BFS through non-black (unknown + white)
        visited = [[False]*M for _ in range(N)]
        stack = [start]
        visited[start[0]][start[1]] = True
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if not visited[nr][nc] and st[nr][nc] != 2:
                    visited[nr][nc] = True
                    stack.append((nr, nc))
        for r in range(N):
            for c in range(M):
                if st[r][c] == 1 and not visited[r][c]:
                    return False
        return True

    def fully_determined(st):
        for r in range(N):
            for c in range(M):
                if st[r][c] == 0:
                    return False
        return True

    def final_connectivity(st):
        # whites must form single connected component
        start = None
        for r in range(N):
            for c in range(M):
                if st[r][c] == 1:
                    start = (r, c); break
            if start: break
        if not start:
            return True
        visited = set()
        stack = [start]
        visited.add(start)
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and st[nr][nc] == 1:
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        for r in range(N):
            for c in range(M):
                if st[r][c] == 1 and (r, c) not in visited:
                    return False
        return True

    def propagate(st):
        # Repeatedly apply deductions
        changed = True
        while changed:
            changed = False
            if not check_adjacency(st): return False
            if not check_clues(st): return False
            if not check_connectivity(st): return False

            # For each clue, if min == n, remaining unknowns in sight must be black (bounded)
            # if max == n, remaining unknowns in sight must be white
            for r, c, n in clues:
                mn, mx = count_visible(st, r, c)
                if mn == n:
                    # All unknown cells that could extend visibility must be black
                    # i.e., first unknown in each direction (after current whites) must be black
                    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        tr, tc = r+dr, c+dc
                        while 0 <= tr < N and 0 <= tc < M and st[tr][tc] == 1:
                            tr += dr; tc += dc
                        if 0 <= tr < N and 0 <= tc < M and st[tr][tc] == 0:
                            st[tr][tc] = 2
                            changed = True
                if mx == n:
                    # All unknown cells in visibility range must be white
                    for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
                        tr, tc = r+dr, c+dc
                        while 0 <= tr < N and 0 <= tc < M and st[tr][tc] != 2:
                            if st[tr][tc] == 0:
                                st[tr][tc] = 1
                                changed = True
                            tr += dr; tc += dc

            # Adjacency: if a cell is black, neighbors must be white
            for r in range(N):
                for c in range(M):
                    if st[r][c] == 2:
                        for nr, nc in neighbors(r, c):
                            if st[nr][nc] == 0:
                                st[nr][nc] = 1
                                changed = True
                            elif st[nr][nc] == 2:
                                return False

            # Cell would disconnect whites if black: must be white
            # Simpler: try each unknown - if making it black disconnects, it must be white
            # (Costly but fine for small grids)
            for r in range(N):
                for c in range(M):
                    if st[r][c] == 0:
                        # tentative black
                        st[r][c] = 2
                        ok = check_connectivity(st) and check_adjacency(st)
                        st[r][c] = 0
                        if not ok:
                            st[r][c] = 1
                            changed = True
                            continue
                        # tentative white - check clue feasibility
                        st[r][c] = 1
                        ok2 = check_clues(st)
                        st[r][c] = 0
                        if not ok2:
                            st[r][c] = 2
                            changed = True
        return True

    def copy_state(st):
        return [row[:] for row in st]

    def backtrack(st):
        if not propagate(st):
            return None
        # find best unknown cell (near a clue with tight constraint)
        target = None
        for r in range(N):
            for c in range(M):
                if st[r][c] == 0:
                    target = (r, c); break
            if target: break
        if not target:
            if check_clues(st) and check_adjacency(st) and final_connectivity(st):
                return st
            return None

        r, c = target
        for val in (2, 1):
            new_st = copy_state(st)
            new_st[r][c] = val
            res = backtrack(new_st)
            if res is not None:
                return res
        return None

    result = backtrack(state)
    if result is None:
        return "No Solution"

    out = []
    for r in range(N):
        row = []
        for c in range(M):
            if grid[r][c] is not None:
                row.append(grid[r][c])
            elif result[r][c] == 2:
                row.append('B')
            else:
                row.append(None)
        out.append(row)
    return str(out)

