def solve(observation):
    board = observation['data']
    R = len(board)
    C = len(board[0])

    # cell states: 'B'=bulb, 'X'=no bulb (forbidden), None=unknown, 'K'=black
    # Build black cell map
    black = [[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if board[r][c] is not None:
                black[r][c] = True

    # state: 0=unknown, 1=bulb, 2=empty(no bulb)
    state = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if black[r][c]:
                state[r][c] = 3  # black

    def neighbors(r, c):
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C:
                yield nr, nc

    def white_neighbors(r, c):
        for nr, nc in neighbors(r, c):
            if not black[nr][nc]:
                yield nr, nc

    # For each white cell, compute "segment": list of cells in the same row-segment and col-segment 
    # (cells that would be illuminated / see each other)
    def get_sight(r, c, st):
        # returns list of white cells (including (r,c)) seen from (r,c) given current state (black blocks)
        cells = [(r, c)]
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < R and 0 <= nc < C and not black[nr][nc]:
                cells.append((nr, nc))
                nr += dr
                nc += dc
        return cells

    # illumination check helper - is cell (r,c) illuminated by any bulb?
    def is_illuminated(r, c, st):
        if st[r][c] == 1:
            return True
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            while 0 <= nr < R and 0 <= nc < C and not black[nr][nc]:
                if st[nr][nc] == 1:
                    return True
                nr += dr
                nc += dc
        return False

    def place_bulb(st, r, c):
        # place bulb at (r,c), mark all seen cells as empty
        if st[r][c] == 2:
            return False
        if st[r][c] == 3:
            return False
        st[r][c] = 1
        for nr, nc in get_sight(r, c, st):
            if (nr, nc) == (r, c):
                continue
            if st[nr][nc] == 1:
                return False
            if st[nr][nc] == 0:
                st[nr][nc] = 2
        return True

    def place_empty(st, r, c):
        if st[r][c] == 1:
            return False
        if st[r][c] == 3:
            return False
        st[r][c] = 2
        return True

    def propagate(st):
