                                    changed = True

            # Illumination constraint: for each unlit unknown white cell, find candidates
            for r in range(R):
                for c in range(C):
                    if black[r][c]:
                        continue
                    if st[r][c] == 1:
                        continue
                    # is it already lit?
                    lit = False
                    candidates = []
                    if st[r][c] == 0:
                        candidates.append((r,c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        while 0 <= nr < R and 0 <= nc < C and not black[nr][nc]:
                            if st[nr][nc] == 1:
