                    if isinstance(board[r][c], int) and board[r][c] >= 0:
                        cnt = sum(1 for nr, nc in white_neighbors(r,c) if st[nr][nc] == 1)
                        if cnt != board[r][c]:
                            return False
                    continue
                if st[r][c] == 0:
                    return False
                if st[r][c] == 2:
                    # check illuminated
                    if not is_illuminated(r, c, st):
                        return False
        return True

    def copy_state(st):
        return [row[:] for row in st]

    def choose_cell(st):
        # choose an unknown cell for branching; prefer cells near numbered black or with fewest candidates
        # Find a numbered black cell with unknowns
        best = None
        best_score = float('inf')
        for r in range(R):
            for c in range(C):
                if black[r][c] and isinstance(board[r][c], int) and board[r][c] >= 0:
                    unk = [(nr,nc) for nr,nc in white_neighbors(r,c) if st[nr][nc] == 0]
                    if unk and len(unk) < best_score:
                        best_score = len(unk)
                        best = unk[0]
        if best:
            return best
        # else find unlit white cell with fewest candidates
        best = None
        best_score = float('inf')
        for r in range(R):
            for c in range(C):
                if black[r][c] or st[r][c] != 0:
                    continue
                # find candidates to light it
                cands = [(r,c)]
                lit = False
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    while 0 <= nr < R and 0 <= nc < C and not black[nr][nc]:
                        if st[nr][nc] == 1:
                            lit = True; break
                        if st[nr][nc] == 0:
                            cands.append((nr,nc))
                        nr += dr; nc += dc
                    if lit: break
                if lit: continue
                if len(cands) < best_score:
                    best_score = len(cands)
                    best = (r,c,cands)
        if best:
            return best[2][0]
        return None

    def backtrack(st):
        if not propagate(st):
            return None
        cell = choose_cell(st)
        if cell is None:
            if is_complete(st):
                return st
            return None
        r, c = cell
        # try bulb
        st1 = copy_state(st)
        if place_bulb(st1, r, c):
            res = backtrack(st1)
            if res is not None:
                return res
        # try empty
        st2 = copy_state(st)
        if place_empty(st2, r, c):
            res = backtrack(st2)
            if res is not None:
                return res
        return None

    result = backtrack(state)
    if result is None:
        return "No Solution"
    answer = [[None]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if result[r][c] == 1:
                answer[r][c] = 'B'
    return str(answer)

