            return None
        # Find unlit white cell with fewest candidates, or unknown cell
        best = None
        best_cands = None
        for (r,c) in white_cells:
            if state[r][c] == 1:
                continue
            lit = False
            candidates = []
            if state[r][c] == 0:
                candidates.append((r,c))
            for (nr, nc) in sight[(r,c)]:
                if state[nr][nc] == 1:
                    lit = True
                    break
                if state[nr][nc] == 0:
                    candidates.append((nr,nc))
            if lit:
                continue
            if not candidates:
                return None
            if best is None or len(candidates) < len(best_cands):
                best = (r,c)
                best_cands = candidates
                if len(candidates) == 1:
                    break

        if best is None:
            if is_complete(state):
                return state
            return None

        for (br, bc) in best_cands:
            new_state = copy_state(state)
            if place_bulb(br, bc, new_state):
                result = backtrack(new_state)
                if result is not None:
                    return result
            # also try marking empty? No - one of candidates must be bulb.
        return None

    result = backtrack(state)
    if result is None:
        return "No Solution"

    answer = [[('B' if result[r][c] == 1 else None) for c in range(C)] for r in range(R)]
    return answer

