        'T': [[(0,0),(0,1),(0,2),(1,1)]],
        'S': [[(0,1),(0,2),(1,0),(1,1)]],
    }
    def rotate(cells):
        return [(c, -r) for r,c in cells]
    def reflect(cells):
        return [(r, -c) for r,c in cells]
    def normalize(cells):
        minr = min(r for r,c in cells)
        minc = min(c for r,c in cells)
        return tuple(sorted((r-minr, c-minc) for r,c in cells))

    result = {}
    for name, base_list in pieces.items():
        variants = set()
        for base in base_list:
            cur = base
            for _ in range(4):
                variants.add(normalize(cur))
                variants.add(normalize(reflect(cur)))
                cur = rotate(cur)
        result[name] = [list(v) for v in variants]
    return result

