    region_ids = list(regions.keys())

    # Region adjacency
    region_adj = defaultdict(set)
    for r in range(R):
        for c in range(C):
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr, c+dc
                if 0<=nr<R and 0<=nc<C:
                    if grid[nr][nc] != grid[r][c]:
