        start = next(iter(shaded))
        visited = {start}
        stack = [start]
        while stack:
            r,c = stack.pop()
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr,nc = r+dr,c+dc
                if (nr,nc) in shaded and (nr,nc) not in visited:
                    visited.add((nr,nc))
                    stack.append((nr,nc))
