            return connected_possible()
        rid = order[idx]
        for ptype, cells in region_placements[rid]:
            # Check adjacent region type constraint
            conflict = False
            for adj in region_adj[rid]:
                if adj in assignment and assignment[adj][0] == ptype:
                    conflict = True
                    break
            if conflict:
                continue
            # Check no 2x2
            if not check_no_2x2(cells):
