            # Simple: proceed
            assignment[rid] = (ptype, cells)
            shaded.update(cells)
            if backtrack(idx+1):
                return True
            for c in cells:
                shaded.discard(c)
            del assignment[rid]
        return False

    if not backtrack(0):
        return "No Solution"

    result = [[None]*C for _ in range(R)]
    for rid, (ptype, cells) in assignment.items():
        for r,c in cells:
            result[r][c] = ptype

    return '\n'.join(' '.join(str(x) if x else '.' for x in row) for row in result)

