        seen = set()
        for start in adj:
            if start in seen: continue
            comp = set()
            stack = [start]
            while stack:
                x = stack.pop()
                if x in comp: continue
                comp.add(x)
                for y in adj[x]:
                    if y not in comp: stack.append(y)
            seen |= comp
            # Check if closed (all deg 2 in this comp)
            all_deg2 = all(len(adj[x]) == 2 for x in comp)
            if all_deg2:
