                    return ('H', r, c)
        for r in range(N-1):
            for c in range(N):
                if V[r][c] == 0:
                    return ('V', r, c)
        return None

    def dfs():
        # Check for premature closed sub-loop
        if not check_no_subloop():
            return None
        e = find_unknown()
        if e is None:
            return check_single_loop()
        for val in (1, -1):
            changes = []
            t, r, c = e
            if t == 'H':
                H[r][c] = val
            else:
                V[r][c] = val
            changes.append(e)
            # propagate
            saved_h = [row[:] for row in H]
            saved_v = [row[:] for row in V]
            result = propagate()
            if result is not None:
                res = dfs()
                if res is not None:
                    return res
            # revert
            for i in range(N):
                for j in range(N-1):
                    H[i][j] = saved_h[i][j]
            for i in range(N-1):
                for j in range(N):
                    V[i][j] = saved_v[i][j]
            # unset e already reverted
        return None

    result = dfs()
    if result is None: return "No Solution"
    return str(result)

