        start = next(iter(adj))
        visited = {start}
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = [x for x in adj[cur] if x != prev]
            if not nxts: return None
            nxt = nxts[0]
            if nxt == start:
                path.append(start)
                break
            if nxt in visited: return None
            visited.add(nxt)
            path.append(nxt)
            prev = cur
            cur = nxt
