        seen = set()
        for start in adj:
            if start in seen: continue
            comp = set()
            stack = [start]
            while stack:
                x = stack.pop()
                if x in comp: continue
                comp.add(x)
                for y in adj[x]:
                    if y not in comp: stack.append(y)
