        # type 'H' or 'V'
        res = []
        if c > 0: res.append(('H', r, c-1))  # left
        if c < N-1: res.append(('H', r, c))  # right
        if r > 0: res.append(('V', r-1, c))  # up
        if r < N-1: res.append(('V', r, c))  # down
        return res

    def get_edge(H, V, e):
        t, r, c = e
        if t == 'H': return H[r][c]
        return V[r][c]

    def set_edge(H, V, e, val):
        t, r, c = e
