                            # Also: the next dot in each direction must continue straight
                            # i.e., the edge beyond must also be ON
                            if h_on == 2: return False
                            if v_on == 2: return False
                            if h_off == len(h_edges):
                                # no H possible -> fail
                                return False
                            if v_off == len(v_edges):
                                return False
                            # If only one H edge is not off, it must be on
                            h_possible = [e for e in h_edges if get_edge(H,V,e) != OFF]
                            v_possible = [e for e in v_edges if get_edge(H,V,e) != OFF]
                            if len(h_possible) == 1 and h_on == 0:
                                if not set_edge(H, V, h_possible[0], ON): return False
                                changed = True
                            if len(v_possible) == 1 and v_on == 0:
                                if not set_edge(H, V, v_possible[0], ON): return False
                                changed = True
                            # For black, if an H edge is ON, the dot beyond on the H side must continue straight
                            # The ON H edge goes to neighbor dot; from that neighbor, we need the opposite H edge ON too? No - 
                            # "goes straight in previous and next steps" means from the black dot, after turning, next step goes straight.
                            # So the edge from black dot is ON, and the next edge (collinear) from the neighbor is also ON.
                            for e in h_edges:
                                if get_edge(H,V,e) == ON:
                                    # extend: neighbor is the far end of this H edge
                                    t, er, ec = e
