                                    if ec == c:  # right edge, neighbor is (r, c+1)
                                        nr, nc = r, c+1
                                        # need edge (nr,nc)-(nr,nc+1) ON
                                        if nc < N-1:
                                            if not set_edge(H, V, ('H', nr, nc), ON): return False
