                            he = [e for e in es if e[0]=='H' and get_edge(H,V,e)==ON]
                            ve = [e for e in es if e[0]=='V' and get_edge(H,V,e)==ON]
                            return len(he)==1 and len(ve)==1
                        left_turn = (c-1 >= 0) and is_turn(r, c-1)
                        right_turn = (c+1 < N) and is_turn(r, c+1)
                        if not (left_turn or right_turn):
                            return False
                    elif len(v_on) == 2:
                        def is_turn(rr, cc):
                            es = get_edges_at(rr, cc)
                            he = [e for e in es if e[0]=='H' and get_edge(H,V,e)==ON]
                            ve = [e for e in es if e[0]=='V' and get_edge(H,V,e)==ON]
                            return len(he)==1 and len(ve)==1
