                on_e = [e for e in edges if get_edge(H,V,e)==ON]
                if len(on_e) == 2:
                    start = (r, c)
                    break
            if start: break
        if not start: return None

        path = [start]
        prev = None
        cur = start
        while True:
            edges = get_edges_at(*cur)
            on_e = [e for e in edges if get_edge(H,V,e)==ON]
            nxt = None
            for e in on_e:
                t, er, ec = e
                if t == 'H':
                    if (er, ec) == cur: other = (er, ec+1)
                    else: other = (er, ec)
                else:
                    if (er, ec) == cur: other = (er+1, ec)
                    else: other = (er, ec)
