                    # Determine direction: H or V
                    edges = get_edges_at(r, c)
                    h_on = [e for e in edges if e[0]=='H' and get_edge(H,V,e)==ON]
                    v_on = [e for e in edges if e[0]=='V' and get_edge(H,V,e)==ON]
                    if len(h_on) == 2:
                        # horizontal through. Check turn at (r,c-1) or (r,c+1)
                        # Turn at dot (r, c') means the two ON edges are perpendicular
                        def is_turn(rr, cc):
                            es = get_edges_at(rr, cc)
                            he = [e for e in es if e[0]=='H' and get_edge(H,V,e)==ON]
                            ve = [e for e in es if e[0]=='V' and get_edge(H,V,e)==ON]
                            return len(he)==1 and len(ve)==1
