                            he = [e for e in es if e[0]=='H' and get_edge(H,V,e)==ON]
                            ve = [e for e in es if e[0]=='V' and get_edge(H,V,e)==ON]
                            return len(he)==1 and len(ve)==1
                        up_turn = (r-1 >= 0) and is_turn(r-1, c)
                        down_turn = (r+1 < N) and is_turn(r+1, c)
                        if not (up_turn or down_turn):
                            return False
        return True

    def extract_loop(H, V):
        # Find starting ON edge
        start = None
        for r in range(N):
            for c in range(N):
                edges = get_edges_at(r, c)
                on_e = [e for e in edges if get_edge(H,V,e)==ON]
                if len(on_e) == 2:
                    start = (r, c)
                    break
            if start: break
        if not start: return None

        path = [start]
        prev = None
        cur = start
        while True:
            edges = get_edges_at(*cur)
            on_e = [e for e in edges if get_edge(H,V,e)==ON]
            nxt = None
            for e in on_e:
                t, er, ec = e
                if t == 'H':
                    if (er, ec) == cur: other = (er, ec+1)
                    else: other = (er, ec)
                else:
                    if (er, ec) == cur: other = (er+1, ec)
                    else: other = (er, ec)
                if other != prev:
                    nxt = other
                    break
            if nxt is None: return None
            if nxt == start:
                path.append(start)
                return path
            path.append(nxt)
            prev = cur
            cur = nxt
            if len(path) > N*N*2: return None

    def count_loops_and_check(H, V):
        # Check if ON edges form single loop (no sub-loops)
        visited_dots = set()
        loops = 0
        total_on_dots = 0
        dot_on = {}
        for r in range(N):
            for c in range(N):
                edges = get_edges_at(r, c)
                on_e = [e for e in edges if get_edge(H,V,e)==ON]
                if len(on_e) > 0:
                    dot_on[(r,c)] = on_e
                    total_on_dots += 1

        for start in dot_on:
            if start in visited_dots: continue
            # Walk
            stack = [start]
            while stack:
                d = stack.pop()
                if d in visited_dots: continue
                visited_dots.add(d)
                for e in dot_on[d]:
                    t, er, ec = e
                    if t == 'H':
                        other = (er, ec+1) if (er,ec)==d else (er,ec)
                    else:
                        other = (er+1, ec) if (er,ec)==d else (er,ec)
                    if other not in visited_dots:
                        stack.append(other)
            loops += 1
        return loops

    solution = [None]

    def dfs(H, V):
        if solution[0] is not None: return
        e = find_unk(H, V)
        if e is None:
            # Check single loop
            # All clues must be on loop (have 2 on edges)
            for r in range(N):
                for c in range(N):
                    if data[r][c] is not None:
                        edges = get_edges_at(r, c)
                        on_count = sum(1 for ee in edges if get_edge(H,V,ee)==ON)
                        if on_count != 2: return
            loops = count_loops_and_check(H, V)
            if loops != 1: return
            if not check_w_turn_constraint(H, V): return
            loop = extract_loop(H, V)
            if loop:
                solution[0] = loop
            return

        for val in (ON, OFF):
            H2, V2 = copy_state(H, V)
            t, r, c = e
            if t == 'H': H2[r][c] = val
            else: V2[r][c] = val
            if propagate(H2, V2):
                # Early check for subloops: if any closed component exists but unks remain, it's invalid only if no unk connects
                # Skip expensive check
                dfs(H2, V2)
                if solution[0] is not None: return

    dfs(H, V)

    if solution[0] is None:
        return "No Solution"
    return str(solution[0])

