    state = [[-1]*C for _ in range(R)]

    # Numbered cells are not mines
    clues = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] is not None:
                state[r][c] = 0
                clues.append((r, c, grid[r][c]))

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < R and 0 <= nc < C:
                    yield nr, nc

    def propagate(state):
