        while changed:
            changed = False
            for r, c, v in clues:
                unknowns = []
                mines = 0
                for nr, nc in neighbors(r, c):
                    if state[nr][nc] == 1:
                        mines += 1
                    elif state[nr][nc] == -1:
                        unknowns.append((nr, nc))
                needed = v - mines
                if needed < 0 or needed > len(unknowns):
                    return False
                if needed == 0 and unknowns:
                    for nr, nc in unknowns:
                        state[nr][nc] = 0
                    changed = True
                elif needed == len(unknowns) and unknowns:
                    for nr, nc in unknowns:
                        state[nr][nc] = 1
                    changed = True
        return True

    if not propagate(state):
        return "No Solution"

    # Subset deduction: for pairs of clues, if one's unknown set is subset of another
    def subset_deduce(state):
        any_change = False
        changed = True
        while changed:
            changed = False
            infos = []
            for r, c, v in clues:
                unknowns = []
                mines = 0
                for nr, nc in neighbors(r, c):
                    if state[nr][nc] == 1:
                        mines += 1
                    elif state[nr][nc] == -1:
                        unknowns.append((nr, nc))
                if unknowns:
                    infos.append((set(unknowns), v - mines))
            for i in range(len(infos)):
                s1, n1 = infos[i]
                for j in range(len(infos)):
                    if i == j:
                        continue
                    s2, n2 = infos[j]
                    if s1 < s2:
                        diff = s2 - s1
                        dn = n2 - n1
                        if dn == 0:
                            for cell in diff:
                                if state[cell[0]][cell[1]] == -1:
                                    state[cell[0]][cell[1]] = 0
                                    changed = True
                                    any_change = True
                        elif dn == len(diff):
                            for cell in diff:
                                if state[cell[0]][cell[1]] == -1:
                                    state[cell[0]][cell[1]] = 1
                                    changed = True
                                    any_change = True
            if changed:
                if not propagate(state):
                    return None
        return any_change

    while True:
        res = subset_deduce(state)
        if res is None:
            return "No Solution"
        if not res:
            break

    # Check if solved
    def is_complete(state):
        for r in range(R):
            for c in range(C):
                if state[r][c] == -1:
                    return False
        return True

    def validate_full(state):
        for r, c, v in clues:
            m = 0
            for nr, nc in neighbors(r, c):
                if state[nr][nc] == 1:
                    m += 1
            if m != v:
                return False
        return True

    if not is_complete(state):
        # Backtracking on remaining unknowns, focus on those adjacent to clues first
        # Find constraint-related unknowns
        def backtrack():
            # Find most constrained clue
            best = None
            best_score = None
            for r, c, v in clues:
                unknowns = []
                mines = 0
                for nr, nc in neighbors(r, c):
