                # set them to non-mine (they don't affect any clue)
                for r in range(R):
                    for c in range(C):
                        if state[r][c] == -1:
                            state[r][c] = 0
                return validate_full(state)

            r, c, v, unknowns, mines = best
            needed = v - mines
            k = len(unknowns)
            # try all combinations of choosing 'needed' mines from unknowns
            from itertools import combinations
            saved = [[row[:] for row in state]]
            for combo in combinations(range(k), needed):
                # restore
                for rr in range(R):
                    for cc in range(C):
                        state[rr][cc] = saved[0][rr][cc]
                mine_set = set(combo)
                for idx, (nr, nc) in enumerate(unknowns):
                    state[nr][nc] = 1 if idx in mine_set else 0
                if not propagate(state):
                    continue
                # subset deduce
                ok = True
                while True:
                    res = subset_deduce(state)
                    if res is None:
                        ok = False
                        break
                    if not res:
                        break
                if not ok:
                    continue
                if backtrack():
                    return True
            # restore
            for rr in range(R):
                for cc in range(C):
                    state[rr][cc] = saved[0][rr][cc]
            return False

        if not backtrack():
            return "No Solution"

    if not validate_full(state):
        return "No Solution"

    result = [['F' if state[r][c] == 1 else None for c in range(C)] for r in range(R)]
    return str(result)

