            if idx == len(clues):
                patterns.append(current)
                return
            remaining = sum(clues[idx:]) + (len(clues) - idx - 1)
            for start in range(pos, length - remaining + 1):
                new = current | (((1 << clues[idx]) - 1) << start)
                place(idx + 1, start + clues[idx] + 1, new)
        if not clues or clues == [0]:
            patterns.append(0)
        else:
            place(0, 0, 0)
        return patterns

    row_patterns = [gen_patterns(r, W) for r in rows]
    col_patterns = [gen_patterns(c, H) for c in cols]

    # Initially compute for each cell, known states based on row/col patterns
    # row_known[r] = (must_black_mask, must_white_mask) for width W
    # Use bitmasks of width W for rows, H for cols

    def refine(patterns, length, must_b, must_w):
        # Filter patterns consistent with must_b and must_w
        new_pats = [p for p in patterns if (p & must_w) == 0 and (p & must_b) == must_b]
        if not new_pats:
            return None, 0, 0
        all_on = new_pats[0]
        all_off = new_pats[0]
        for p in new_pats[1:]:
            all_on &= p
            all_off |= p
        new_must_b = all_on
        new_must_w = ((1 << length) - 1) & ~all_off
        return new_pats, new_must_b, new_must_w

    # row_b[r]: bitmask width W of cells known black in row r
    # row_w[r]: bitmask width W of cells known white
    row_b = [0]*H
    row_w = [0]*H
    col_b = [0]*W
    col_w = [0]*W

    # Initial refine
    for r in range(H):
        row_patterns[r], row_b[r], row_w[r] = refine(row_patterns[r], W, 0, 0)
        if row_patterns[r] is None:
            return "No Solution"
    for c in range(W):
        col_patterns[c], col_b[c], col_w[c] = refine(col_patterns[c], H, 0, 0)
        if col_patterns[c] is None:
