                row_w[i] = saved_rw[i]
            for i in range(W):
                col_b[i] = saved_cb[i]
                col_w[i] = saved_cw[i]

            row_patterns[best_r] = [pattern]
            row_b[best_r] = pattern
            row_w[best_r] = ((1 << W) - 1) & ~pattern

            if propagate():
                if solve_rec():
