                    if grid[mr][c1] is None:
                        grid[mr][c1] = 'B'
                else:
                    # diagonal - the two cells between them must not both be white
                    # actually both could be black or one could be
                    # they'd form path. Cells are (r1,c2) and (r2,c1). At least one must be black
                    pass
            elif d == 1:
                # adjacent clues - impossible unless same island (but diff clues)
                return "No Solution"

    if not propagate(grid):
        return "No Solution"

    # Now backtracking search on unknown cells
    # Choose cell that is most constrained

    def find_unknown(g):
        # Prefer cell adjacent to a white island that's not yet full (MRV-like)
        best = None
        for r in range(R):
            for c in range(C):
                if g[r][c] is None:
                    # score: adjacent to decided cells
                    score = 0
                    for nr,nc in neighbors(r,c):
                        if g[nr][nc] is not None:
                            score += 1
                    if best is None or score > best[0]:
                        best = (score, r, c)
                        if score == 4:
                            return (r,c)
        if best is None:
            return None
        return (best[1], best[2])

    def final_check(g):
        # All cells decided. Check all rules strictly.
        # 1. No 2x2 black
        if not check_no_2x2_black(g):
            return False
        # 2. Black connectivity
        black_cells = [(r,c) for r in range(R) for c in range(C) if g[r][c]=='B']
        if black_cells:
            start = black_cells[0]
            seen = {start}
            q = deque([start])
            while q:
                r,c = q.popleft()
                for nr,nc in neighbors(r,c):
                    if (nr,nc) in seen: continue
                    if g[nr][nc]=='B':
                        seen.add((nr,nc))
                        q.append((nr,nc))
            if len(seen) != len(black_cells):
                return False
        # 3. White islands match clues
        seen = set()
        for r in range(R):
            for c in range(C):
                if g[r][c]=='W' and (r,c) not in seen:
                    cells, _, cs_found = white_island_info(g, r, c)
                    seen |= cells
                    if len(cs_found) != 1:
                        return False
                    cr,cc = cs_found[0]
                    if len(cells) != clue_map[(cr,cc)]:
                        return False
        return True

    def backtrack(g):
        cell = find_unknown(g)
        if cell is None:
            if final_check(g):
                return g
            return None
        r,c = cell
        for val in ('W', 'B'):
            # copy
            ng = [row[:] for row in g]
            ng[r][c] = val
            if propagate(ng):
                result = backtrack(ng)
                if result is not None:
                    return result
        return None

    result = backtrack(grid)
    if result is None:
        return "No Solution"

    # Build output
    out = [[('B' if result[r][c]=='B' else None) for c in range(C)] for r in range(R)]
    return str(out)

