def solve(observation):
    data = observation['data']
    adj = observation['adjacent']
    N = len(data)

    # Build adjacency sets: horizontal_dot[r][c] = True if dot between (r,c) and (r,c+1)
    # vertical_dot[r][c] = True if dot between (r,c) and (r+1,c)
    h_dot = [[False]*(N-1) for _ in range(N)]
    v_dot = [[False]*N for _ in range(N-1)]

    for (a, b) in adj:
        if a == int(a):  # row is integer -> horizontal gap
            r = int(a)
            c = int(b - 0.5)
            if 0 <= r < N and 0 <= c < N-1:
                h_dot[r][c] = True
        else:  # row has .5 -> vertical gap
            r = int(a - 0.5)
            c = int(b)
            if 0 <= r < N-1 and 0 <= c < N:
                v_dot[r][c] = True

    # Domain for each cell
    domains = [[set(range(1, N+1)) for _ in range(N)] for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[r][c] = {data[r][c]}

    # Apply adjacency constraints to prune domains
    # For neighboring cells, compatible values must differ by 1 (dot) or not by 1 (no dot)

    def get_neighbors(r, c):
        result = []
        if c+1 < N:
            result.append((r, c+1, h_dot[r][c]))
        if c-1 >= 0:
            result.append((r, c-1, h_dot[r][c-1]))
        if r+1 < N:
            result.append((r+1, c, v_dot[r][c]))
        if r-1 >= 0:
            result.append((r-1, c, v_dot[r-1][c]))
        return result

    def propagate():
        changed = True
        while changed:
            changed = False
            # Singleton elimination in rows/cols
            for r in range(N):
                for c in range(N):
                    if len(domains[r][c]) == 1:
                        v = next(iter(domains[r][c]))
                        for cc in range(N):
                            if cc != c and v in domains[r][cc]:
                                domains[r][cc].discard(v)
                                if not domains[r][cc]:
                                    return False
                                changed = True
                        for rr in range(N):
                            if rr != r and v in domains[rr][c]:
                                domains[rr][c].discard(v)
                                if not domains[rr][c]:
                                    return False
                                changed = True
            # Adjacency pruning
            for r in range(N):
                for c in range(N):
                    new_dom = set()
                    for v in domains[r][c]:
                        ok = True
                        for (nr, nc, has_dot) in get_neighbors(r, c):
                            if has_dot:
                                # need some value in neighbor with |v - v2| == 1
                                if not any(abs(v - v2) == 1 for v2 in domains[nr][nc]):
                                    ok = False
                                    break
                            else:
                                # need some value in neighbor with |v - v2| != 1
                                if not any(abs(v - v2) != 1 for v2 in domains[nr][nc]):
                                    ok = False
                                    break
                        if ok:
                            new_dom.add(v)
                    if new_dom != domains[r][c]:
                        if not new_dom:
                            return False
                        domains[r][c] = new_dom
                        changed = True
            # Hidden singles in rows/cols
            for r in range(N):
                for v in range(1, N+1):
                    cells = [c for c in range(N) if v in domains[r][c]]
                    if len(cells) == 0:
                        return False
                    if len(cells) == 1 and len(domains[r][cells[0]]) > 1:
                        domains[r][cells[0]] = {v}
                        changed = True
            for c in range(N):
                for v in range(1, N+1):
                    cells = [r for r in range(N) if v in domains[r][c]]
                    if len(cells) == 0:
                        return False
                    if len(cells) == 1 and len(domains[cells[0]][c]) > 1:
                        domains[cells[0]][c] = {v}
                        changed = True
        return True

    if not propagate():
        return "No Solution"

    # Backtracking
    def check_adj(r, c, v, grid):
        for (nr, nc, has_dot) in get_neighbors(r, c):
            if grid[nr][nc] is not None:
                if has_dot and abs(v - grid[nr][nc]) != 1:
                    return False
                if not has_dot and abs(v - grid[nr][nc]) == 1:
                    return False
        return True

    grid = [[None]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if len(domains[r][c]) == 1:
                grid[r][c] = next(iter(domains[r][c]))

    row_used = [set() for _ in range(N)]
    col_used = [set() for _ in range(N)]
    for r in range(N):
        for c in range(N):
            if grid[r][c] is not None:
                row_used[r].add(grid[r][c])
                col_used[c].add(grid[r][c])

    def backtrack():
        # Find cell with smallest domain
        best = None
        best_size = 10**9
        for r in range(N):
            for c in range(N):
                if grid[r][c] is None:
                    cands = domains[r][c] - row_used[r] - col_used[c]
                    if len(cands) < best_size:
                        best_size = len(cands)
                        best = (r, c, cands)
                        if best_size == 0:
                            return False
        if best is None:
            return True
        r, c, cands = best
        for v in cands:
            if not check_adj(r, c, v, grid):
                continue
            grid[r][c] = v
            row_used[r].add(v)
            col_used[c].add(v)
            if backtrack():
                return True
            grid[r][c] = None
            row_used[r].discard(v)
            col_used[c].discard(v)
        return False

    if not backtrack():
        return "No Solution"

    return "\n".join(" ".join(str(x) for x in row) for row in grid)

