                comp.add(v)
                if len(adj[v]) != 2:
                    closed = False
                for nb in adj[v]:
                    if nb not in comp:
                        stack.append(nb)
            visited |= comp
            if closed:
                # all dots in comp have degree 2; it's a closed loop
                # if there are any unknown edges adjacent to dots outside comp, it's premature
                # simplest: premature if not all clues are in comp OR there are unknown edges at all
                # Actually: if closed loop exists, any unknown edge outside means premature
                has_unknown_outside = False
                for r in range(N1):
                    for c in range(N):
                        if H[r][c] == 0:
                            has_unknown_outside = True; break
                    if has_unknown_outside: break
                if not has_unknown_outside:
                    for r in range(N):
                        for c in range(N1):
                            if V[r][c] == 0:
                                has_unknown_outside = True; break
                        if has_unknown_outside: break
                if has_unknown_outside:
                    return True  # premature
                # No unknowns: check all clues are in this component
                for (cr,cc) in clues:
                    if (cr,cc) not in comp:
                        return True
        return False

    path = dfs()
    if path is None:
        return "No Solution"
    return str(path)

