                    if s==1: on_count+=1
                    elif s==0: unk.append(eid)
                if unk and on_count>=1:
                    score = on_count*10 + (4-len(unk))
                    if score>best_score:
                        best_score=score; best=unk[0]
        if best: return best
        # fallback: any unknown
        for r in range(NH_r):
            for c in range(NH_c):
                if H_edge[r][c]==0: return ('H',r,c)
        for r in range(NV_r):
            for c in range(NV_c):
                if V_edge[r][c]==0: return ('V',r,c)
        return None

    def search(state):
        if solution[0] is not None: return
        if not propagate(state): return
        if not partial_loop_check(state): return
        eid = pick_edge(state)
        if eid is None:
            # complete
            if loop_check(state) and validate_clues(state):
                solution[0] = copy_state(state)
            return
        for val in (1,2):
            ns = copy_state(state)
            set_edge(ns, eid, val)
            search(ns)
            if solution[0] is not None: return

    state = new_state()
    search(state)

    if solution[0] is None:
        return "No Solution"
    path = build_path(solution[0])
    return str(path)

