# Slitherlink-variant (Masyu-like with sum clues): loop on dot grid.
# Edges between adjacent dots; each dot has degree 0 or 2.
# White circle at dot: loop passes straight through (two opposite edges used).
# Black circle at dot: loop turns (one horizontal + one vertical edge used).
# Number k = sum of lengths of two straight segments extending from that circle.
# For a straight-through white: lengths = #edges extending in each direction until a turn.
# For a black (turn): lengths of the two straight segments in the two chosen directions.

import sys
sys.setrecursionlimit(100000)

def solve(observation):
    data = observation['data']
    R = len(data)
    C = len(data[0])
    # dots are at (r,c) for r in [0,R-1], c in [0,C-1]
    # edges: horizontal H[r][c] connects (r,c)-(r,c+1); vertical V[r][c] connects (r,c)-(r+1,c)

    clues = {}  # (r,c) -> ('W' or 'B', k)
    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if v:
                clues[(r,c)] = (v[0], int(v[1:]))

    # Edge state: 0 unknown, 1 on, -1 off
    # We represent as dicts
    H = [[0]*(C-1) for _ in range(R)]  # H[r][c]: (r,c)-(r,c+1)
    V = [[0]*C for _ in range(R-1)]    # V[r][c]: (r,c)-(r+1,c)

    def h_get(r,c): return H[r][c]
    def v_get(r,c): return V[r][c]
    def h_set(r,c,v): H[r][c] = v
    def v_set(r,c,v): V[r][c] = v

    # Incident edges of dot (r,c): returns list of (kind, r, c, direction)
    # direction: 0=E,1=W,2=S,3=N
    def incident(r,c):
        edges = []
        if c < C-1: edges.append(('H', r, c, 'E'))       # east
        if c > 0:   edges.append(('H', r, c-1, 'W'))     # west
        if r < R-1: edges.append(('V', r, c, 'S'))       # south
        if r > 0:   edges.append(('V', r-1, c, 'N'))     # north
        return edges

    def get_edge(kind, r, c):
        return H[r][c] if kind=='H' else V[r][c]
    def set_edge(kind, r, c, v):
        if kind=='H': H[r][c]=v
        else: V[r][c]=v

    # For clue constraints, need to enumerate possible configurations.
    # Brute search with propagation. We'll use DFS over edges with constraints.

    # Precompute all edges list
    edges_list = []
    for r in range(R):
        for c in range(C-1):
            edges_list.append(('H', r, c))
    for r in range(R-1):
        for c in range(C):
            edges_list.append(('V', r, c))

    # For each clue, generate list of allowed edge-configurations at that dot.
    # A config specifies which of the 4 incident edges are ON (and implicitly bounds straight segment lengths).
    # But the straight segment length depends on edges beyond the clue, which may not be fully known.
    # So we'll defer checking until assignment progresses. Instead, we'll do DFS with frontier propagation.

    # Strategy: Build loop by tracing. Start from some edge that must be on.
    # Simpler: iterate all edges in a fixed order, try on/off, propagate constraints:
    #   - Each non-clue dot: degree in {0,2}.
    #   - Clue W: degree must be 2 and the two on-edges must be collinear (opposite).
    #   - Clue B: degree must be 2 and the two on-edges must be perpendicular.
    #   - No small closed loops (only one loop at end).
    #   - Sum constraint k at clue.

    # We'll iterate dots/edges and use constraint propagation via recursive search on undecided edges,
    # picking the most constrained dot next.

    # Determine for each dot: min/max possible degree given current states.
    def dot_state(r,c):
        on=0; unk=0; edges=[]
        for (k,er,ec,d) in incident(r,c):
            s = get_edge(k,er,ec)
            edges.append((k,er,ec,d,s))
            if s==1: on+=1
            elif s==0: unk+=1
        return on, unk, edges

    # Propagate constraints until no change. Return False if contradiction.
    def propagate():
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    on,unk,edges = dot_state(r,c)
                    cl = clues.get((r,c))
                    if cl is None:
                        # degree 0 or 2
                        if on>2: return False
                        if on==2:
                            # turn off all unknowns
                            for (k,er,ec,d,s) in edges:
                                if s==0:
                                    set_edge(k,er,ec,-1); changed=True
                        elif on==1:
                            if unk==0: return False
                            if unk==1:
                                for (k,er,ec,d,s) in edges:
                                    if s==0:
                                        set_edge(k,er,ec,1); changed=True
                        elif on==0:
                            if unk==1:
                                for (k,er,ec,d,s) in edges:
                                    if s==0:
                                        set_edge(k,er,ec,-1); changed=True
                    else:
                        typ,kval = cl
                        # degree must be 2
                        if on>2: return False
                        if on+unk<2: return False
                        # W: opposite pair. B: perpendicular pair.
                        # Check feasibility of combinations
                        dirs = {'E':None,'W':None,'S':None,'N':None}
                        for (k,er,ec,d,s) in edges:
                            dirs[d] = (k,er,ec,s)
                        # possible pairs
                        if typ=='W':
                            pairs = [('E','W'),('N','S')]
                        else:
                            pairs = [('E','N'),('E','S'),('W','N'),('W','S')]
                        feasible = []
                        for (a,b) in pairs:
                            if dirs[a] is None or dirs[b] is None: continue
                            sa = dirs[a][3]; sb = dirs[b][3]
                            if sa==-1 or sb==-1: continue
                            # other two must be off-able
                            ok=True
                            for d in dirs:
                                if d==a or d==b: continue
                                if dirs[d] is not None and dirs[d][3]==1:
                                    ok=False; break
                            if ok: feasible.append((a,b))
                        if not feasible: return False
                        # If only one feasible pair, set accordingly
                        if len(feasible)==1:
                            a,b = feasible[0]
                            for d in dirs:
                                if dirs[d] is None: continue
                                k,er,ec,s = dirs[d]
                                want = 1 if d in (a,b) else -1
                                if s==0:
                                    set_edge(k,er,ec,want); changed=True
                                elif s!=want:
                                    return False
                        else:
                            # Check if some direction forced on/off across all feasible pairs
                            on_in_all = set(feasible[0])
                            off_in_all = set(['E','W','N','S']) - set(feasible[0])
                            for p in feasible[1:]:
                                on_in_all &= set(p)
                                off_in_all &= (set(['E','W','N','S']) - set(p))
                            for d in on_in_all:
                                if dirs[d] is not None:
                                    k,er,ec,s = dirs[d]
                                    if s==0:
                                        set_edge(k,er,ec,1); changed=True
                                    elif s==-1:
                                        return False
                            for d in off_in_all:
                                if dirs[d] is not None:
                                    k,er,ec,s = dirs[d]
                                    if s==0:
                                        set_edge(k,er,ec,-1); changed=True
                                    elif s==1:
                                        return False
        return True

    # Check sum constraints where determinable. For each clue, compute possible straight-segment sums given current edge states.
    # For a white clue at (r,c): goes straight in H or V. Determine which (maybe propagate).
    # Length extending east = number of consecutive H edges E from (r,c)... until we hit a dot that is a turn (not straight).
    # Complex; we'll check only when fully determined (leaf check), but also use partial bounds.

    def straight_len(r, c, dr, dc):
        """Length of straight segment starting from (r,c) going direction (dr,dc).
           Counts edges while edges in that direction are ON and the dots passed through continue straight.
           Returns (length, fully_known). If any edge on path is unknown, returns best-known lower bound and False.
        """
        length = 0
        known = True
        cr, cc = r, c
        while True:
            nr, nc = cr+dr, cc+dc
            if not (0<=nr<R and 0<=nc<C): break
            # edge from (cr,cc) to (nr,nc)
            if dr==0:
                ec = min(cc,nc)
                s = H[cr][ec]
            else:
                er = min(cr,nr)
                s = V[er][cc]
            if s==1:
                length += 1
                # check at new dot (nr,nc): does it continue straight?
                # it continues if the edge going further in same direction is ON; else stops.
                cr, cc = nr, nc
                # continue loop
            elif s==-1:
                break
            else:
                known = False
                break
        return length, known

    def check_sums(final=False):
        for (r,c),(typ,k) in clues.items():
            on,unk,edges = dot_state(r,c)
            dirs = {}
            for (kk,er,ec,d,s) in edges:
                dirs[d]=(kk,er,ec,s)
            if typ=='W':
                # Determine axis: if any of E/W is ON -> horizontal; N/S ON -> vertical
                horiz = False; vert=False
                for d in ('E','W'):
                    if d in dirs and dirs[d][3]==1: horiz=True
                for d in ('N','S'):
                    if d in dirs and dirs[d][3]==1: vert=True
                if horiz and vert: return False
                if horiz:
                    lE,kE = straight_len(r,c,0,1) if 'E' in dirs else (0,True)
                    lW,kW = straight_len(r,c,0,-1) if 'W' in dirs else (0,True)
                    total = lE+lW
                    if kE and kW:
                        if total != k: return False
                    else:
                        if total > k: return False
                elif vert:
                    lS,kS = straight_len(r,c,1,0) if 'S' in dirs else (0,True)
                    lN,kN = straight_len(r,c,-1,0) if 'N' in dirs else (0,True)
                    total = lS+lN
                    if kS and kN:
                        if total != k: return False
                    else:
                        if total > k: return False
                else:
                    # undetermined, skip if not final
                    if final: return False
            else:  # Black
                # Two perpendicular edges on
                on_dirs = [d for d in ('E','W','N','S') if d in dirs and dirs[d][3]==1]
                if len(on_dirs)==2:
                    a,b = on_dirs
                    if {a,b} in ({'E','W'},{'N','S'}): return False
                    # compute straight length in each direction starting from (r,c)
                    dd = {'E':(0,1),'W':(0,-1),'S':(1,0),'N':(-1,0)}
                    la,ka = straight_len(r,c,*dd[a])
                    lb,kb = straight_len(r,c,*dd[b])
                    total = la+lb
                    if ka and kb:
                        if total != k: return False
                    else:
                        if total > k: return False
                elif len(on_dirs)<2 and final:
                    return False
                else:
                    # partial: compute upper bound of possible sums; if lowest lower>k return False
                    pass
        return True

    # Check that we don't have multiple closed loops prematurely
    def check_no_premature_loop(final=False):
        # Build graph from ON edges; find connected components and check each dot has deg 0 or 2.
        # If final, must be single loop through all clues.
        adj = {}
        for r in range(R):
            for c in range(C-1):
                if H[r][c]==1:
                    adj.setdefault((r,c),[]).append((r,c+1))
                    adj.setdefault((r,c+1),[]).append((r,c))
        for r in range(R-1):
            for c in range(C):
                if V[r][c]==1:
                    adj.setdefault((r,c),[]).append((r+1,c))
                    adj.setdefault((r+1,c),[]).append((r,c))
        if not adj:
            return not final
        # Check each component
        visited = set()
        comps = []
        for node in adj:
            if node in visited: continue
            stack=[node]; comp=set()
            while stack:
                x=stack.pop()
                if x in visited: continue
                visited.add(x); comp.add(x)
                for y in adj[x]:
                    if y not in visited: stack.append(y)
            comps.append(comp)
        # Check if any component is a closed loop while there are unknowns outside or other components
        # A closed loop component: every node in it has degree 2 (no unknown incident edges that could extend).
        # If we find a closed loop but other ON edges exist or unknown incident -> premature.
        for comp in comps:
            closed = True
            for node in comp:
                r,c = node
                on,unk,_ = dot_state(r,c)
                if on!=2 or unk>0:
                    # wait unknown incident might still be pruned; but if on==2 then unknowns should be set off by propagation
                    if on!=2:
                        closed = False
                        break
            if closed:
                if len(comps)>1:
                    return False
                # single closed loop: must cover all clues
                for cl in clues:
                    if cl not in comp: return False
                if not final:
                    # If it's a full closed loop and all edges decided consistent -> this is solution candidate.
                    pass
        return True

    # Find unknown edge with most constraint: adjacent to a dot with on==1 or near a clue with ambiguity.
    def choose_edge():
        best = None; best_score = -1
        for r in range(R):
            for c in range(C):
                on,unk,edges = dot_state(r,c)
                if unk==0: continue
                # score: higher if on==1 (forced next), or clue with few options
                score = 0
                if on==1: score += 100
                if (r,c) in clues: score += 50
                score += (4-unk)
                for (k,er,ec,d,s) in edges:
                    if s==0:
                        if score > best_score:
                            best_score = score
                            best = (k,er,ec)
                        break
        return best

    solution = [None]

    def dfs(depth=0):
        if solution[0] is not None: return
        if not propagate(): return
        if not check_sums(False): return
        if not check_no_premature_loop(False): return
        edge = choose_edge()
        if edge is None:
            # fully determined
            if check_sums(True) and check_loop_final():
                solution[0] = extract_loop()
            return
        k,er,ec = edge
        # save state
        saved_H = [row[:] for row in H]
        saved_V = [row[:] for row in V]
        for val in (1,-1):
            set_edge(k,er,ec,val)
            dfs(depth+1)
            if solution[0] is not None: return
            # restore
            for i in range(R): H[i]=saved_H[i][:]
            for i in range(R-1): V[i]=saved_V[i][:]

    def check_loop_final():
        # all edges decided; check single loop through all clues
        adj={}
        for r in range(R):
            for c in range(C-1):
                if H[r][c]==1:
                    adj.setdefault((r,c),[]).append((r,c+1))
                    adj.setdefault((r,c+1),[]).append((r,c))
        for r in range(R-1):
            for c in range(C):
                if V[r][c]==1:
                    adj.setdefault((r,c),[]).append((r+1,c))
                    adj.setdefault((r+1,c),[]).append((r,c))
        if not adj: return False
        # all degrees 2
        for n,nb in adj.items():
            if len(nb)!=2: return False
        # connected
        start = next(iter(adj))
        visited={start}; stack=[start]
        while stack:
            x=stack.pop()
            for y in adj[x]:
                if y not in visited:
                    visited.add(y); stack.append(y)
        if len(visited)!=len(adj): return False
        for cl in clues:
            if cl not in adj: return False
        return True

    def extract_loop():
        adj={}
        for r in range(R):
            for c in range(C-1):
                if H[r][c]==1:
                    adj.setdefault((r,c),[]).append((r,c+1))
                    adj.setdefault((r,c+1),[]).append((r,c))
        for r in range(R-1):
            for c in range(C):
                if V[r][c]==1:
                    adj.setdefault((r,c),[]).append((r+1,c))
                    adj.setdefault((r+1,c),[]).append((r,c))
        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start
        while True:
            nxts = [n for n in adj[cur] if n != prev]
            nxt = nxts[0]
            if nxt == start:
                path.append(start); break
            path.append(nxt)
            prev, cur = cur, nxt
        return path

    dfs()
    if solution[0] is None:
        return "No Solution"
    return str(solution[0])

