                        if 0 <= nr <= H-1 and 0 <= nc <= W-1:
                            if dr == 0:
                                idx = min(c,nc)
                                e = h[r][idx]
                                eloc = ('h', r, idx)
                            else:
                                idx = min(r,nr)
                                e = v[idx][c]
                                eloc = ('v', idx, c)
                            if e == 1: n1 += 1
                            elif e == -1: unknowns.append(eloc)
                    if n1 > 2: return False
                    if n1 == 2:
                        for el in unknowns:
                            if el[0] == 'h': h[el[1]][el[2]] = 0
                            else: v[el[1]][el[2]] = 0
                            changed = True
                    elif n1 == 1 and len(unknowns) == 1:
                        el = unknowns[0]
                        if el[0] == 'h': h[el[1]][el[2]] = 1
                        else: v[el[1]][el[2]] = 1
                        changed = True
                    elif n1 == 0 and len(unknowns) == 1:
                        # must be 0
                        el = unknowns[0]
                        if el[0] == 'h': h[el[1]][el[2]] = 0
                        else: v[el[1]][el[2]] = 0
                        changed = True
                    elif n1 == 1 and len(unknowns) == 0:
                        return False
        return True

    if not propagate_edges(h_final, v_final):
        return "No Solution"

    # Search remaining unknowns
    def find_unknown(h, v):
        for r in range(H):
            for c in range(W-1):
                if h[r][c] == -1:
                    return ('h', r, c)
        for r in range(H-1):
            for c in range(W):
                if v[r][c] == -1:
                    return ('v', r, c)
        return None

    def check_loop(h, v):
        # collect all dots with degree 2
        adj = {}
        for r in range(H):
            for c in range(W):
                neighbors = []
                for (dr,dc) in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr <= H-1 and 0 <= nc <= W-1:
                        if dr == 0:
                            e = h[r][min(c,nc)]
                        else:
                            e = v[min(r,nr)][c]
                        if e == 1:
                            neighbors.append((nr,nc))
                if neighbors:
                    adj[(r,c)] = neighbors
        if not adj: return None
        # Walk
        start = next(iter(adj))
        visited = {start}
        path = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            if len(nbrs) != 2: return None
            nxt = None
            for n in nbrs:
                if n != prev:
                    nxt = n
                    break
            if nxt is None: return None
            if nxt == start:
                path.append(start)
                break
            if nxt in visited: return None
            visited.add(nxt)
            path.append(nxt)
            prev = cur
            cur = nxt
        if len(visited) != len(adj): return None
        return path

    def search(h, v):
        u = find_unknown(h, v)
        if u is None:
            return check_loop(h, v)
        for val in [1, 0]:
            h2 = [row[:] for row in h]
            v2 = [row[:] for row in v]
            if u[0] == 'h':
                h2[u[1]][u[2]] = val
            else:
                v2[u[1]][u[2]] = val
            if not propagate_edges(h2, v2):
                continue
            # Quick loop check: detect premature small loop
            res = search(h2, v2)
            if res is not None:
                return res
        return None

    path = search(h_final, v_final)
    if path is None:
        return "No Solution"

    return str(path)

