def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    def visible(seq):
        m = 0
        c = 0
        for x in seq:
            if x > m:
                c += 1
                m = x
        return c

    # Precompute all permutations of 1..N with their visibility counts from both ends
    from itertools import permutations
    all_perms = []
    for p in permutations(range(1, N+1)):
        all_perms.append(p)

    # For each row, filter perms matching L[r] and R[r]
    row_candidates = []
    for r in range(N):
        cands = []
        for p in all_perms:
            if visible(p) == L[r] and visible(p[::-1]) == R[r]:
                cands.append(p)
        row_candidates.append(cands)

    # Check columns too for initial filtering via col clues when we place
    grid = [[0]*N for _ in range(N)]

    # Sort rows by number of candidates (fewest first) but keep track of original index
    order = sorted(range(N), key=lambda r: len(row_candidates[r]))

    solution = [None]

    def col_valid_partial(col_vals, top_clue, bot_clue, full):
        # col_vals: list of length N with 0 for empty
        if full:
            if visible(col_vals) != top_clue:
                return False
            if visible(col_vals[::-1]) != bot_clue:
                return False
            return True
        # Partial: check no duplicates (already handled), and check upper bound on visibility
        # For top clue: count visible so far among filled prefix contiguous from top
        # Simpler: just check if it's still possible
        # Check top: count visible in filled cells from top, treating unfilled as unknown
        # Minimum visible from top: count in actual sequence where unfilled must be at least something
        # Easier prune: if the filled prefix from top already exceeds clue, fail
        m = 0
        c = 0
        for x in col_vals:
            if x == 0:
                break
            if x > m:
                c += 1
                m = x
        if c > top_clue:
            return False
        # similar from bottom
        m = 0
        c = 0
        for x in reversed(col_vals):
            if x == 0:
                break
            if x > m:
                c += 1
                m = x
        if c > bot_clue:
            return False
        return True

    def backtrack(idx, placed_rows):
        if idx == N:
            # verify columns
            for c in range(N):
                col = [grid[r][c] for r in range(N)]
                if visible(col) != U[c] or visible(col[::-1]) != D[c]:
                    return False
            solution[0] = [row[:] for row in grid]
            return True

        r = order[idx]
        for perm in row_candidates[r]:
            # Check column constraints: no duplicates
            ok = True
            for c in range(N):
                for rr in placed_rows:
                    if grid[rr][c] == perm[c]:
                        ok = False
                        break
                if not ok:
                    break
            if not ok:
                continue

            # Place
            for c in range(N):
                grid[r][c] = perm[c]
            placed_rows.append(r)

            # Column partial check
            col_ok = True
            for c in range(N):
                col = [grid[rr][c] for rr in range(N)]
                # Check if column is complete
                full = all(v != 0 for v in col)
                if not col_valid_partial(col, U[c], D[c], full):
                    col_ok = False
                    break

            if col_ok:
                if backtrack(idx + 1, placed_rows):
                    return True

            placed_rows.pop()
            for c in range(N):
                grid[r][c] = 0

        return False

    if backtrack(0, []):
        return '\n'.join(' '.join(str(x) for x in row) for row in solution[0])
    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

