    for r in range(N):
        cands = []
        for p in permutations(range(1, N+1)):
            if L[r] and count_visible(p) != L[r]:
                continue
            if R[r] and count_visible(p[::-1]) != R[r]:
                continue
            cands.append(p)
        row_candidates.append(cands)

    # Sort rows by number of candidates (fewer first) but keep original indices
    # Actually we need to fill in order to check column constraints properly
    # Use backtracking row by row

    grid = [None] * N

    def check_col_partial(col_idx, filled_rows):
        # filled_rows = number of rows filled (0..N)
        col = [grid[r][col_idx] for r in range(filled_rows)]
        # uniqueness
        if len(set(col)) != len(col):
            return False
        if filled_rows == N:
            if U[col_idx] and count_visible(col) != U[col_idx]:
                return False
            if D[col_idx] and count_visible(col[::-1]) != D[col_idx]:
                return False
        else:
