            if U[col_idx]:
                # min visible = current visible (if max in partial stays max, but remaining could add more)
                visible_so_far = count_visible(col)
                max_so_far = max(col) if col else 0
                # remaining cells could add visible buildings if taller than max_so_far
                remaining = N - filled_rows
                # max possible additional visible = number of distinct values > max_so_far among remaining possibilities
                # simpler: max visible <= visible_so_far + remaining
                if visible_so_far > U[col_idx]:
                    return False
                if visible_so_far + remaining < U[col_idx]:
                    return False
        return True

    def backtrack(r):
        if r == N:
            # final column check for D and U
            for c in range(N):
                col = [grid[i][c] for i in range(N)]
                if U[c] and count_visible(col) != U[c]:
                    return False
                if D[c] and count_visible(col[::-1]) != D[c]:
                    return False
            return True

        for cand in row_candidates[r]:
            grid[r] = cand
            ok = True
            for c in range(N):
                if not check_col_partial(c, r+1):
                    ok = False
                    break
            if ok:
                if backtrack(r+1):
                    return True
        grid[r] = None
        return False

    if backtrack(0):
        return str([list(row) for row in grid])
    return "No Solution"

