# Slant puzzle solver
# Each cell has '/' or '\'
# '/' connects bottom-left (r+1,c) to top-right (r,c+1)
# '\' connects top-left (r,c) to bottom-right (r+1,c+1)
# Clue at dot (r,c) = number of diagonals incident to it
# No closed loops allowed

import sys
sys.setrecursionlimit(100000)

def solve(observation):
    data = observation['data']
    N = len(data) - 1

    # For each dot (r,c), list the adjacent cells and which diagonal type touches this dot
    # Dot (r,c) is touched by:
    #   cell (r-1,c-1) if it is '\' (bottom-right corner of that cell)
    #   cell (r-1,c)   if it is '/' (bottom-left corner)
    #   cell (r,c-1)   if it is '/' (top-right corner)
    #   cell (r,c)     if it is '\' (top-left corner)

    def dot_neighbors(r, c):
        # returns list of (cell_r, cell_c, required_char)
        res = []
        if r-1 >= 0 and c-1 >= 0:
            res.append((r-1, c-1, '\\'))
        if r-1 >= 0 and c < N:
            res.append((r-1, c, '/'))
        if r < N and c-1 >= 0:
            res.append((r, c-1, '/'))
        if r < N and c < N:
