        for (dr, dc, ch) in [(-1,-1,'\\'), (-1,0,'/'), (0,-1,'/'), (0,0,'\\')]:
            cr, cc = r+dr, c+dc
            if 0 <= cr < N and 0 <= cc < N:
                res.append((cr, cc, ch))
        return res

