    for r in range(N+1):
        for c in range(N+1):
            if data[r][c] is not None:
                clues.append((r, c, data[r][c], dot_neighbors(r, c)))

    # Grid: None = unset, '/' or '\' = set
    grid = [[None]*N for _ in range(N)]

    # Union-find for loop detection
    # Each dot is a node. Adding a diagonal merges two dots.
    # If two dots already connected -> forms loop.
    parent = list(range((N+1)*(N+1)))

    def dot_id(r, c):
        return r*(N+1) + c

    def find(x, par):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x

    def try_set(grid, parent, r, c, ch):
        # Returns (success, undo_info)
        # undo_info: (r, c, parent_changes)
        if ch == '/':
            a = dot_id(r+1, c)
            b = dot_id(r, c+1)
        else:
            a = dot_id(r, c)
            b = dot_id(r+1, c+1)
        ra = find(a, parent)
        rb = find(b, parent)
        if ra == rb:
            return False, None
        grid[r][c] = ch
        old = (ra, parent[ra])
        parent[ra] = rb
        return True, (r, c, old)

    def undo(grid, parent, info):
        r, c, (ra, oldp) = info
        grid[r][c] = None
        parent[ra] = oldp

