        for (cr, cc, ch) in neighbors:
            g = grid[cr][cc]
            if g is None:
                unset += 1
            elif g == ch:
                cur += 1
        if cur > val:
            return False, None
        if cur + unset < val:
            return False, None
        return True, (cur, unset)

    # Propagation: for each clue, if cur == val, all unset neighbors must be the OTHER diagonal
    # if cur + unset == val, all unset neighbors must be the required diagonal

    def propagate(grid, parent):
        # returns list of undo infos, or None if contradiction
        undos = []
        changed = True
        while changed:
            changed = False
            for (r, c, val, neighbors) in clues:
                cur = 0
                unset_list = []
                for (cr, cc, ch) in neighbors:
                    g = grid[cr][cc]
                    if g is None:
