                    elif g == ch:
                        cur += 1
                if cur > val:
                    return None, undos
                need = val - cur
                if need < 0 or need > len(unset_list):
                    return None, undos
                if need == 0 and unset_list:
                    for (cr, cc, ch) in unset_list:
                        other = '/' if ch == '\\' else '\\'
                        ok, info = try_set(grid, parent, cr, cc, other)
                        if not ok:
                            return None, undos
                        undos.append(info)
                        changed = True
                elif need == len(unset_list) and unset_list:
