            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    # We'll use a history-based union-find for backtracking
    uf_history = []

    def union(a, b):
        # Returns True if successful (no cycle), False if cycle
        ra, rb = find(a), find(b)
        if ra == rb:
            return False  # would create cycle
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        # attach rb under ra
        uf_history.append(('union', rb, parent[rb], ra, rank[ra]))
        parent[rb] = ra
        if rank[ra] == rank[rb]:
