        best_r = best_c = -1
        for r in range(N):
            for c in range(N):
                if solved[r][c] == 0:
                    cnt = popcount(cand[r][c])
                    if best == -1 or cnt < best:
                        best = cnt
                        best_r, best_c = r, c
                        if cnt <= 1:
                            break
            if best == 1:
                break
        if best == -1:
            return True
        m = cand[best_r][best_c]
        v = 1
        while m:
            if m & 1:
                # save state
                sv_solved = [row[:] for row in solved]
                sv_cand = [row[:] for row in cand]
                if place(best_r, best_c, v):
