            if v is not None:
                bit = 1 << (v - 1)
                grid[r][c] = v
                rows[r] |= bit
                cols[c] |= bit
                boxes[box_idx2(r, c)] |= bit

    def candidates(r, c):
        return ALL & ~(rows[r] | cols[c] | boxes[box_idx2(r, c)])

    def bit_count(x):
        return bin(x).count('1')

    def solve_recursive():
        # Find cell with fewest candidates (MRV)
        best = -1
        best_count = N + 1
        best_cands = 0
        for r in range(N):
