                        best_count = cnt
                        best = (r, c)
                        best_cands = cands
                        if cnt == 1:
                            break
            if best_count == 1:
                break

        if best == -1:
            return True

        r, c = best
        bi = box_idx2(r, c)
        cands = best_cands
        while cands:
            bit = cands & -cands
            cands ^= bit
            v = bit.bit_length()
            grid[r][c] = v
            rows[r] |= bit
            cols[c] |= bit
            boxes[bi] |= bit
            if solve_recursive():
                return True
            grid[r][c] = 0
            rows[r] ^= bit
            cols[c] ^= bit
            boxes[bi] ^= bit
        return False

