            adj = {t: [cell for cell in tree_to_cands[t] if state.get(cell)==1] for t in trees}
            match = {}
            def try_match(t, visited):
                for cell in adj[t]:
                    if cell in visited: continue
                    visited.add(cell)
                    if cell not in match or try_match(match[cell], visited):
                        match[cell] = t
                        return True
                return False
            for t in trees:
