            # All trees have at least one tent neighbor; verify matching exists
            # Build bipartite: trees -> tents (state==1), check perfect matching
            tents_placed = [cell for cell in state if state[cell] == 1]
            if len(tents_placed) != len(trees):
                return False
            # Check row/col counts
            for r in range(R):
                if row_placed[r] != row_counts[r]: return False
            for c in range(C):
                if col_placed[c] != col_counts[c]: return False
            # Bipartite matching
            adj = {t: [cell for cell in tree_to_cands[t] if state.get(cell)==1] for t in trees}
            match = {}
            def try_match(t, visited):
                for cell in adj[t]:
                    if cell in visited: continue
                    visited.add(cell)
