            return False

        for cell in best_opts:
            snap = snapshot()
            if set_tent(cell, []) and propagate():
                if search():
                    return True
            restore(snap)
        return False

    if not search():
        return "No Solution"

    result = [[None]*C for _ in range(R)]
    for cell, v in state.items():
        if v == 1:
            result[cell[0]][cell[1]] = 't'
    return str(result)

