        return sum(1 for c in range(C) if grid[r][c] == state)

    def count_col(c, state):
        return sum(1 for r in range(R) if grid[r][c] == state)

    def place_tent(r, c, g):
        # Returns False if conflict
        if g[r][c] == 1:
            return True
        if g[r][c] == 2:
            return False
        g[r][c] = 1
        # All 8-neighbors become grass
        for nr, nc in neighbors8(r, c):
            if g[nr][nc] == 1:
                # conflict if not same
                if (nr, nc) != (r, c):
                    return False
            elif g[nr][nc] == 0:
                g[nr][nc] = 2
        return True

