        if g[r][c] == 1:
            return False
        g[r][c] = 2
        return True

    def propagate(g):
        changed = True
        while changed:
            changed = False
            # Row constraint
            for r in range(R):
                tents = sum(1 for c in range(C) if g[r][c] == 1)
                unknowns = [c for c in range(C) if g[r][c] == 0]
                need = row_counts[r] - tents
                if need < 0 or need > len(unknowns):
                    return False
                if need == 0:
                    for c in unknowns:
                        if not set_grass(r, c, g):
                            return False
                        changed = True
                elif need == len(unknowns):
                    for c in unknowns:
                        if not place_tent(r, c, g):
                            return False
                        changed = True
            # Col constraint
            for c in range(C):
                tents = sum(1 for r in range(R) if g[r][c] == 1)
                unknowns = [r for r in range(R) if g[r][c] == 0]
                need = col_counts[c] - tents
                if need < 0 or need > len(unknowns):
                    return False
                if need == 0:
                    for r in unknowns:
                        if not set_grass(r, c, g):
                            return False
                        changed = True
                elif need == len(unknowns):
                    for r in unknowns:
                        if not place_tent(r, c, g):
                            return False
                        changed = True

            # Tree constraint: each tree must have at least one possible tent neighbor
            # If only one possible spot, place it
            for tr, tc in tree_list:
                # find tents already adjacent (that could be paired with this tree)
                # Actually, harder: tree needs a tent adjacent. If exactly one unknown/tent neighbor that's not grass, must be tent
                possible = []
                has_tent = False
                for nr, nc in neighbors4(tr, tc):
                    if g[nr][nc] == 0:
                        possible.append((nr, nc))
                    elif g[nr][nc] == 1:
                        has_tent = True
                        break
                if has_tent:
                    continue
                if len(possible) == 0:
                    return False
                if len(possible) == 1:
                    nr, nc = possible[0]
                    if not place_tent(nr, nc, g):
                        return False
                    changed = True
        return True

    if not propagate(grid):
        return "No Solution"

    # Now we need to verify a valid tree-tent matching exists and complete the puzzle
    # Use backtracking: pick cell with fewest options

    def check_matching(g):
        # Bipartite matching: trees to adjacent tent cells (tent cells that are =1 or could be =1? 
        # For final check: tents placed (=1) must match 1-1 to trees
        tents = [(r,c) for r in range(R) for c in range(C) if g[r][c]==1]
        if len(tents) != len(tree_list):
            return False
        # Match each tent to an adjacent tree
        tree_idx = {t:i for i,t in enumerate(tree_list)}
        adj = []
        for (r,c) in tents:
            opts = []
            for nr,nc in neighbors4(r,c):
                if is_tree[nr][nc]:
                    opts.append(tree_idx[(nr,nc)])
            adj.append(opts)
        # Hungarian / simple augmenting path
        match_tree = [-1]*len(tree_list)
        def try_match(u, visited):
            for v in adj[u]:
                if visited[v]: continue
                visited[v] = True
                if match_tree[v] == -1 or try_match(match_tree[v], visited):
                    match_tree[v] = u
                    return True
            return False
        for u in range(len(tents)):
            visited = [False]*len(tree_list)
            if not try_match(u, visited):
                return False
        return True

    def solve_rec(g):
        # Check if solved
        done = True
        best = None
        best_score = float('inf')
        for r in range(R):
            for c in range(C):
                if g[r][c] == 0:
                    done = False
                    # Score based on row/col remaining
                    rr = row_counts[r] - sum(1 for cc in range(C) if g[r][cc]==1)
                    cc_r = col_counts[c] - sum(1 for rr2 in range(R) if g[rr2][c]==1)
                    score = rr + cc_r
                    if score < best_score:
                        best_score = score
                        best = (r, c)
        if done:
            if check_matching(g):
                return g
            return None

        r, c = best
        # Try tent first if row/col need, else grass first
        for val in [1, 2]:
            ng = [row[:] for row in g]
            if val == 1:
                if not place_tent(r, c, ng):
                    continue
            else:
                ng[r][c] = 2
            if not propagate(ng):
                continue
            result = solve_rec(ng)
            if result:
                return result
        return None

    sys.setrecursionlimit(10000)
    result = solve_rec(grid)
    if result is None:
        return "No Solution"

    ans = [['t' if result[r][c]==1 else None for c in range(C)] for r in range(R)]
    return str(ans)

