        for r in range(N-1):
            for c in range(N-1):
                cells = [g[r][c], g[r][c+1], g[r+1][c], g[r+1][c+1]]
                if all(x == 'B' for x in cells):
                    return False
                if all(x == 'W' for x in cells):
                    return False
        return True

    def connectivity_possible(g, color):
        # Check that all cells of given color can potentially be connected
        # via cells that are either that color or None.
        cells = [(r,c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells:
            return True
        # BFS from first cell through color or None
        start = cells[0]
        visited = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and g[nr][nc] in (color, None):
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return all(cell in visited for cell in cells)

    def fully_connected(g, color):
        cells = [(r,c) for r in range(N) for c in range(N) if g[r][c] == color]
        if not cells:
            return True
        start = cells[0]
        visited = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and g[nr][nc] == color:
                    visited.add((nr, nc))
                    stack.append((nr, nc))
        return len(visited) == len(cells)

    def propagate(g):
        # Apply deterministic rules until fixpoint or contradiction
        changed = True
        while changed:
            changed = False
            # Rule 1: 2x2 avoidance - if 3 cells of a 2x2 are same color, 4th must be opposite
            for r in range(N-1):
                for c in range(N-1):
                    cells = [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
                    vals = [g[rr][cc] for rr,cc in cells]
                    for color, opp in (('B','W'),('W','B')):
                        same = [i for i,v in enumerate(vals) if v == color]
                        none_i = [i for i,v in enumerate(vals) if v is None]
                        if len(same) == 3 and len(none_i) == 1:
                            rr, cc = cells[none_i[0]]
                            g[rr][cc] = opp
