                        g[r][c] = 'W'
                        okW = connectivity_possible(g, 'W') and connectivity_possible(g, 'B')
                        g[r][c] = None
                        if not okB and not okW:
                            return False
                        if not okB:
                            g[r][c] = 'W'
                            changed = True
                        elif not okW:
                            g[r][c] = 'B'
                            changed = True
        return True

    def is_valid(g):
        if not check_2x2(g):
            return False
        if not fully_connected(g, 'B'):
            return False
        if not fully_connected(g, 'W'):
            return False
        return True

