                            if 0 <= rr < N-1 and 0 <= cc < N-1:
                                vals = [g[rr][cc],g[rr][cc+1],g[rr+1][cc],g[rr+1][cc+1]]
                                filled = sum(1 for v in vals if v is not None)
                                score += filled
                    if score > best_score:
                        best_score = score
                        best = (r, c)
        return best

    def solve_rec(g):
        if not propagate(g):
            return None
        # Find empty cell
        cell = find_best_cell(g)
        if cell is None:
            if is_valid(g):
                return g
            return None
        r, c = cell
        for color in ('B', 'W'):
            ng = [row[:] for row in g]
            ng[r][c] = color
            result = solve_rec(ng)
            if result is not None:
                return result
        return None

    result = solve_rec(grid)
    if result is None:
        return "No Solution"
    return [row[:] for row in result]

