        return True

    def find_best_cell(g):
        # Pick cell adjacent to known cells with most constraints
        best = None
        best_score = -1
        for r in range(N):
            for c in range(N):
                if g[r][c] is None:
                    score = 0
                    for nr, nc in neighbors(r, c):
                        if g[nr][nc] is not None:
                            score += 1
                    # Also prefer cells near 2x2 conflicts
                    for dr in (-1, 0):
                        for dc in (-1, 0):
                            rr, cc = r+dr, c+dc
                            if 0 <= rr < N-1 and 0 <= cc < N-1:
                                vals = [g[rr][cc],g[rr][cc+1],g[rr+1][cc],g[rr+1][cc+1]]
