    def solve_rec(g):
        if not propagate(g):
            return None
        # Find empty cell
        cell = find_best_cell(g)
        if cell is None:
            if is_valid(g):
                return g
            return None
        r, c = cell
        for color in ('B', 'W'):
            ng = [row[:] for row in g]
            ng[r][c] = color
            result = solve_rec(ng)
            if result is not None:
                return result
        return None

    result = solve_rec(grid)
    if result is None:
        return "No Solution"
    return [row[:] for row in result]

