                    if 0 <= nr < N and 0 <= nc < N and g[nr][nc] == color and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        q.append((nr,nc))
            if len(visited) != len(cells):
                return False
        return True

    def choose_cell(g):
        # Prefer unknown cell adjacent to most constraints (a 2x2 with 2 same-color cells)
        best = None
        best_score = -1
        for r in range(N):
            for c in range(N):
                if g[r][c] != 0:
                    continue
                score = 0
                for dr in (-1, 0):
                    for dc in (-1, 0):
                        rr, cc = r+dr, c+dc
                        if 0 <= rr < N-1 and 0 <= cc < N-1:
                            vals = [g[rr][cc], g[rr+1][cc], g[rr][cc+1], g[rr+1][cc+1]]
                            for color in (1, 2):
                                if vals.count(color) >= 2:
                                    score += vals.count(color)
                # adjacency to known
                for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < N and 0 <= nc < N and g[nr][nc] != 0:
                        score += 1
                if score > best_score:
                    best_score = score
                    best = (r,c)
        return best

    def copy_grid(g):
        return [row[:] for row in g]

    solution = [None]

    def backtrack(g):
        if solution[0] is not None:
            return
        # propagate
        if not propagate(g):
            return
        if not connectivity_feasible(g):
            return
        # find unknown
        cell = choose_cell(g)
        if cell is None:
            # fully assigned, check connectivity
            if fully_connected(g) and check_all_2x2(g):
                solution[0] = copy_grid(g)
            return
        r, c = cell
        for color in (1, 2):
            g2 = copy_grid(g)
            g2[r][c] = color
            # quick check 2x2 around this
            if not check_2x2(g2, r, c):
                continue
            backtrack(g2)
            if solution[0] is not None:
                return

    backtrack(grid)

    if solution[0] is None:
        return "No Solution"
    res = solution[0]
    return [['B' if res[r][c]==1 else 'W' for c in range(N)] for r in range(N)]

if __name__ == "__main__":
    print(solve(OBSERVATION))
